1	/**
2	 * The ONE switch for customer/public dedicated-server surfaces.
3	 *
4	 * A viewer may see them when EITHER
5	 *   - Setting dedicated_public_enabled is on (the public launch), OR
6	 *   - they are a private-preview account for "dedicated" (lib/preview-access.ts,
7	 *     Setting preview_access_emails; default: the owner's own customer account).
8	 * Everyone else gets a plain 404, exactly as if the route did not exist.
9	 *
10	 * Every customer route (app/(marketing)/dedicated-servers, app/dashboard/dedicated/**)
11	 * calls `requireDedicatedAccess()` first, and every customer server action calls
12	 * `dedicatedAccessFor(user)`. Admin previews (app/admin/preview/dedicated/**) do
13	 * NOT use this gate — they are admin-only and render with `preview` set.
14	 *
15	 * Indexing/sitemap/nav: the sitemap lists the page only when the PUBLIC flag is
16	 * on; metadata is noindex unless public; the portal nav entry is shown only to
17	 * viewers who pass this gate.
18	 *
19	 * test/dedicated-gate.test.ts asserts all of the above.
20	 */
21	import { notFound } from "next/navigation";
22	import { getSettingBool } from "../settings";
23	import { currentUser } from "../auth";
24	import { isPreviewUser } from "../preview-access";
25	import { DEDICATED_COUNTRY_PAGES, dedicatedCountryPath } from "./regions";
26	
27	export const DEDICATED_PUBLIC_FLAG = "dedicated_public_enabled";
28	export const DEDICATED_PUBLIC_PATH = "/dedicated-servers";
29	export const DEDICATED_DASHBOARD_PATH = "/dashboard/dedicated";
30	export const DEDICATED_ORDER_PATH = "/dashboard/dedicated/order";
31	
32	/** Pure decision (unit-tested): render, or 404. */
33	export function dedicatedRouteDecision(flagOn: boolean, previewUser = false): "render" | "not-found" {
34	  return flagOn || previewUser ? "render" : "not-found";
35	}
36	
37	export async function dedicatedPublicEnabled(): Promise<boolean> {
38	  try {
39	    return await getSettingBool(DEDICATED_PUBLIC_FLAG, false);
40	  } catch {
41	    return false; // fail CLOSED: a DB hiccup must never expose an unreleased page
42	  }
43	}
44	
45	export type DedicatedAccess = { allowed: boolean; isPublic: boolean; preview: boolean };
46	
47	/** Access for an already-loaded user (server actions, layouts). Never throws. */
48	export async function dedicatedAccessFor(user: { email?: string | null } | null | undefined): Promise<DedicatedAccess> {
49	  const isPublic = await dedicatedPublicEnabled();
50	  const preview = !isPublic && (await isPreviewUser(user, "dedicated"));
51	  return { allowed: dedicatedRouteDecision(isPublic, preview) === "render", isPublic, preview };
52	}
53	
54	/** Route guard: 404 unless the viewer may see dedicated servers. */
55	export async function requireDedicatedAccess(): Promise<DedicatedAccess> {
56	  let user = null;
57	  try {
58	    user = await currentUser();
59	  } catch {
60	    user = null;
61	  }
62	  const access = await dedicatedAccessFor(user);
63	  if (!access.allowed) notFound();
64	  return access;
65	}
66	
67	/** Sitemap paths contributed by this feature (empty unless PUBLIC — a preview never advertises). */
68	export function dedicatedSitemapPaths(flagOn: boolean): string[] {
69	  return flagOn ? [DEDICATED_PUBLIC_PATH, ...DEDICATED_COUNTRY_PAGES.map((p) => dedicatedCountryPath(p.slug))] : [];
70	}
71	
72	/** Every bare-metal marketing path (the main page + country pages): never in the NXM route sitemap list. */
73	export const DEDICATED_MARKETING_PATHS: string[] = [DEDICATED_PUBLIC_PATH, ...DEDICATED_COUNTRY_PAGES.map((p) => dedicatedCountryPath(p.slug))];
74	/**
75	 * The portal rail entry for dedicated servers. Added by app/dashboard/layout.tsx
76	 * ONLY for viewers who pass lib/dedicated/gate.ts (public flag on, or a
77	 * private-preview account). Kept here so no file outside the feature names the
78	 * route (test/dedicated-gate.test.ts).
79	 */
80	import type { NavItem } from "../nx/nav";
81	
82	/**
83	 * "Bare Metal" opens the catalogue -> configure -> pay flow. An owned server's
84	 * page (/dashboard/dedicated/<id>) lights My Services instead (subActive), the
85	 * same place every other owned service lives.
86	 */
87	export const DEDICATED_NAV_ITEM: NavItem = { group: "Compute", label: "Bare Metal", icon: "bmrack", href: "/dashboard/dedicated", badge: "NEW", subActive: "/dashboard/services" };
88	/**
89	 * The "Dedicated" tab in the NXM nav (desktop bar, Products dropdown, mobile
90	 * sheet). The nav is the design package's baked HTML, so the entries are
91	 * injected at render time next to stable anchors, and ONLY for viewers who pass
92	 * the dedicated gate (lib/dedicated/gate.ts: public flag, or a private-preview
93	 * account). Everyone else gets the nav byte-for-byte unchanged. Launch = the
94	 * Setting dedicated_public_enabled; no code change.
95	 */
96	const DESKTOP_ANCHOR = '<a class="nv-t" href="/nxm/matrix">Matrix</a>';
97	const DROPDOWN_ANCHOR = "<span><b>VPS Hosting</b><small>Full-root NVMe KVM servers</small></span></a>";
98	const SHEET_ANCHOR = '<a href="/nxm/vps">VPS Hosting</a>';
99	
100	const DESKTOP = '<a class="nv-t" href="/nxm/dedicated-servers">Bare Metal</a>';
101	const DROPDOWN =
102	  '<a class="nv-it" href="/nxm/dedicated-servers"><svg class="nv-ic" viewBox="0 0 24 24" aria-hidden="true"><use width="24" height="24" href="#i-cpu"/></svg><span><b>Bare Metal Dedicated Servers <em class="">New</em></b><small>Single-tenant AMD &amp; Intel, full root</small></span></a>';
103	const SHEET = '<a href="/nxm/dedicated-servers">Bare Metal Dedicated Servers</a>';
104	
105	export function withDedicatedNav(html: string, show: boolean): string {
106	  if (!show) return html;
107	  return html
108	    .replace(DESKTOP_ANCHOR, DESKTOP + DESKTOP_ANCHOR)
109	    .replace(DROPDOWN_ANCHOR, DROPDOWN_ANCHOR + DROPDOWN)
110	    .replace(SHEET_ANCHOR, SHEET_ANCHOR + SHEET);
111	}
