113	/** "Need more power?" strip on the VPS, pricing and game-server pages, gated exactly like the tab. */
114	const UPSELL_PAGES = new Set(["vps", "pricing", "game-servers"]);
115	const UPSELL_ANCHOR = '<section class="section" id="faq"';
116	const UPSELL =
117	  '<section class="section" aria-label="Dedicated servers" style="padding-top:0"><div class="container">' +
118	  '<div class="au-glass" style="display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;padding:22px 26px;border-radius:22px;background:linear-gradient(100deg,rgba(26,85,207,.22),rgba(111,46,224,.16))">' +
119	  '<div style="min-width:0;max-width:62ch"><p style="margin:0 0 6px;font:600 .74rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:#8fd8ff">Need more power?</p>' +
120	  '<p style="margin:0;font-size:1.18rem;font-weight:800;letter-spacing:-.02em;color:#fff">Bare metal dedicated servers: the whole machine, nobody else on it.</p>' +
121	  '<p style="margin:6px 0 0;color:var(--ink-2);font-size:.95rem">Full root, in-stock builds online within 24 hours, managed from the same dashboard.</p></div>' +
122	  '<a class="nxm-glassbtn" href="/nxm/dedicated-servers"><span class="nxm-bt">See bare metal servers</span><span class="nxm-arw" aria-hidden="true">→</span></a>' +
123	  "</div></div></section>";
