125	export function withDedicatedUpsell(html: string, slug: string, show: boolean): string {
126	  if (!show || !UPSELL_PAGES.has(slug) || !html.includes(UPSELL_ANCHOR)) return html;
127	  return html.replace(UPSELL_ANCHOR, UPSELL + UPSELL_ANCHOR);
