131	 * Homepage: a bare-metal strip just before the closing "final" section, gated
132	 * exactly like the tab (same anchor-insertion technique; the homepage markup is
133	 * generated, so nothing is edited in place).
134	 */
135	const HOME_ANCHOR = '<section class="final" id="final"';
136	const HOME_STRIP =
137	  '<section class="section" aria-label="Bare metal dedicated servers" style="padding-top:0"><div class="container">' +
