154	/**
155	 * Dedicated servers are UNRELEASED: with Setting dedicated_public_enabled off
156	 * (the default) the customer/public routes must 404 for everyone except a
157	 * private-preview account (lib/preview-access.ts), must not be in the sitemap,
158	 * and nothing customer-facing outside the feature may link to them.
159	 *
160	 * DATABASE_URL is pointed at a closed port BEFORE the gate is imported, so the
161	 * flag read fails — which must fail CLOSED (404), never open.
162	 */
163	process.env.DATABASE_URL = "postgresql://nobody:nothing@127.0.0.1:1/none?connect_timeout=2";
164	
165	const ROOT = path.resolve(__dirname, "..");
166	const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");
167	
168	const CUSTOMER_ROUTES = [
169	  "app/(marketing)/dedicated-servers/page.tsx",
170	  "app/dashboard/dedicated/page.tsx",
171	  "app/dashboard/dedicated/[id]/page.tsx",
172	  "app/dashboard/dedicated/order/page.tsx",
173	  "app/dashboard/dedicated/order/[id]/page.tsx",
174	];
