176	test("route decision: off = not-found, on = render, preview user = render", async () => {
177	  const { dedicatedRouteDecision, dedicatedSitemapPaths } = await import("../lib/dedicated/gate.ts");
178	  assert.equal(dedicatedRouteDecision(false), "not-found");
179	  assert.equal(dedicatedRouteDecision(false, false), "not-found");
180	  assert.equal(dedicatedRouteDecision(false, true), "render");
181	  assert.equal(dedicatedRouteDecision(true), "render");
182	  assert.deepEqual(dedicatedSitemapPaths(false), []);
183	  const on = dedicatedSitemapPaths(true);
184	  assert.equal(on[0], "/dedicated-servers");
185	  assert.ok(on.includes("/dedicated-servers/singapore"), "country pages are advertised at launch");
186	  assert.ok(on.every((p) => p.startsWith("/dedicated-servers")));
187	});
