189	test("the gate 404s when the flag / allowlist cannot be read (fail closed)", async () => {
190	  const { requireDedicatedAccess, dedicatedPublicEnabled, dedicatedAccessFor } = await import("../lib/dedicated/gate.ts");
191	  assert.equal(await dedicatedPublicEnabled(), false);
192	  // Even the default preview email is refused when the DB can't be read.
193	  assert.deepEqual(await dedicatedAccessFor({ email: "nicholas.sj.albanese@gmail.com" }), { allowed: false, isPublic: false, preview: false });
194	  assert.equal((await dedicatedAccessFor(null)).allowed, false);
195	  await assert.rejects(requireDedicatedAccess(), (e: unknown) => {
196	    const digest = String((e as { digest?: string })?.digest ?? (e as Error)?.message ?? "");
197	    return /NEXT_HTTP_ERROR_FALLBACK;404|NEXT_NOT_FOUND/.test(digest);
198	  });
199	});
