206	test("every customer/public dedicated route calls the gate before doing anything else", () => {
207	  for (const f of CUSTOMER_ROUTES) {
208	    const src = read(f);
209	    assert.match(src, /import \{[^}]*requireDedicatedAccess[^}]*\} from "@\/lib\/dedicated\/gate"/, f);
210	    const body = src.slice(src.indexOf("export default async function"));
211	    const firstAwait = /await\s+([A-Za-z]+)\(/.exec(body);
212	    assert.equal(firstAwait?.[1], "requireDedicatedAccess", `${f}: the gate must be the first await`);
213	    // never indexable while unreleased
214	    if (f.startsWith("app/dashboard/")) assert.match(src, /robots:\s*\{\s*index:\s*false/, `${f}: must be noindex`);
215	  }
