289	/** Every source file under a directory. */
290	function walk(dir: string, out: string[] = []): string[] {
291	  for (const e of readdirSync(path.join(ROOT, dir))) {
292	    const rel = `${dir}/${e}`;
293	    if (e === "node_modules" || e.startsWith(".")) continue;
294	    const st = statSync(path.join(ROOT, rel));
295	    if (st.isDirectory()) walk(rel, out);
296	    else if (/\.(tsx?|json|mjs)$/.test(e)) out.push(rel);
297	  }
298	  return out;
299	}
