function drawCoreFallback(ctx: CanvasRenderingContext2D, t: number, dark: boolean) {
  const R = RADIUS.core;
  const body = ctx.createRadialGradient(-R * 0.25, -R * 0.35, R * 0.1, 0, 0, R);
  if (dark) {
    body.addColorStop(0, "rgb(40 36 110)");
    body.addColorStop(0.55, "rgb(14 14 46)");
    body.addColorStop(1, "rgb(6 6 22)");
  } else {
    body.addColorStop(0, "rgb(255 255 255)");
    body.addColorStop(0.6, "rgb(238 233 255)");
    body.addColorStop(1, "rgb(214 204 253)");
  }
  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.arc(0, 0, R, 0, Math.PI * 2);
  ctx.fill();
  const fres = ctx.createRadialGradient(0, 0, R * 0.6, 0, 0, R);
  fres.addColorStop(0, "rgb(139 92 246 / 0)");
  fres.addColorStop(1, dark ? "rgb(139 92 246 / 0.55)" : "rgb(124 58 237 / 0.3)");
  ctx.fillStyle = fres;
  ctx.fill();
  ctx.lineWidth = 3;
  for (let i = 0; i < 48; i++) {
    const a0 = (i / 48) * Math.PI * 2;
    const c = rimColor(a0 + t * 0.05);
    ctx.strokeStyle = `rgb(${dark ? c : inkOf(c)})`;
    ctx.beginPath();
    ctx.arc(0, 0, R - 1.5, a0, a0 + (Math.PI * 2) / 48 + 0.01);
    ctx.stroke();
  }
