/** Darkens a neon colour so it reads on a white background. */
export function inkOf(rgb: string) {
  const [r, g, b] = rgb.split(" ").map(Number);
  const m = (c: number, t: number) => Math.round(c * 0.7 + t * 0.3);
  return `${m(r, 40)} ${m(g, 20)} ${m(b, 90)}`;
}

/** Mixes a colour toward white. */
export function mix(rgb: string, t: number) {
  const [r, g, b] = rgb.split(" ").map(Number);
  return `${Math.round(r + (255 - r) * t)} ${Math.round(g + (255 - g) * t)} ${Math.round(b + (255 - b) * t)}`;
}

