/** How far `a` must move to stop overlapping `b` (along the cheaper axis), or null if clear. */
function separation(a: Box, b: Box, pad = 6): [number, number] | null {
  const ox = Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0);
  const oy = Math.min(a.y1, b.y1) - Math.max(a.y0, b.y0);
  if (ox <= 0 || oy <= 0) return null;
  const acx = (a.x0 + a.x1) / 2;
  const bcx = (b.x0 + b.x1) / 2;
  const acy = (a.y0 + a.y1) / 2;
  const bcy = (b.y0 + b.y1) / 2;
  if (ox < oy) return [(acx < bcx ? -1 : 1) * (ox + pad), 0];
  return [0, (acy < bcy ? -1 : 1) * (oy + pad)];
}

/**
 * Nudges categories apart so their discs, labels and mod lists never overlap each other, a
 * game or the core. Runs on the default layout only; dragged positions are the user's call.
 */
function relax(nodes: LNode[]) {
  const games = nodes.filter((n) => n.type === "game");
  const cats = nodes.filter((n) => n.type === "category");
  const gameById = new Map(games.map((g) => [g.id, g]));
  const rows = new Map<string, number>();
  const listW = new Map<string, number>();
  for (const n of nodes) {
    if (n.type !== "mod" && n.type !== "more") continue;
    rows.set(n.parent!, n.rows);
    listW.set(n.parent!, Math.max(listW.get(n.parent!) ?? 90, Math.min(200, 44 + n.label.length * 6.4)));
  }
  const pos = new Map(cats.map((c) => [c.id, { x: gameById.get(c.parent!)!.hx + c.hx, y: gameById.get(c.parent!)!.hy + c.hy }]));
  const boxOf = (c: LNode): Box => {
    const p = pos.get(c.id)!;
    const r = rows.get(c.id) ?? 1;
    const lw = listW.get(c.id) ?? 120;
    const labelW = 36 + c.label.length * 7.6 + 24;
    const half = Math.max(30, (r * ROW_H) / 2 + 4);
    if (c.side === "right") return { x0: p.x - 28 - labelW, x1: p.x + 78 + lw, y0: p.y - half, y1: p.y + half };
    if (c.side === "left") return { x0: p.x - 78 - lw, x1: p.x + 28 + labelW, y0: p.y - half, y1: p.y + half };
    const hw = Math.max(lw / 2, labelW / 2, 40);
    if (c.side === "up") return { x0: p.x - hw, x1: p.x + hw, y0: p.y - 60 - r * ROW_H, y1: p.y + 52 };
    return { x0: p.x - hw, x1: p.x + hw, y0: p.y - 52, y1: p.y + 60 + r * ROW_H };
  };
  const fixed: Box[] = [
    { x0: -132, x1: 132, y0: -132, y1: 150 },
    ...games.map((g) => ({ x0: g.hx - 62, x1: g.hx + 62, y0: g.hy - 62, y1: g.hy + 78 })),
  ];
  for (let it = 0; it < 90; it++) {
    let moved = false;
    for (let i = 0; i < cats.length; i++) {
      const pi = pos.get(cats[i].id)!;
      for (const f of fixed) {
        const d = separation(boxOf(cats[i]), f);
        if (d) {
          pi.x += d[0];
          pi.y += d[1];
          moved = true;
        }
      }
      for (let j = i + 1; j < cats.length; j++) {
        const d = separation(boxOf(cats[i]), boxOf(cats[j]));
        if (!d) continue;
        const pj = pos.get(cats[j].id)!;
        pi.x += d[0] / 2;
        pi.y += d[1] / 2;
        pj.x -= d[0] / 2;
        pj.y -= d[1] / 2;
        moved = true;
      }
    }
    if (!moved) break;
  }
  for (const c of cats) {
    const g = gameById.get(c.parent!)!;
    const p = pos.get(c.id)!;
    c.hx = Math.round(p.x - g.hx);
    c.hy = Math.round(p.y - g.hy);
  }
}

/** Half-extents of the whole layout at rest, for fitting the overview camera. */
export function layoutExtent(nodes: LNode[]) {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  let halfW = 260;
  let halfH = 260;
  for (const n of nodes) {
    if (n.type !== "category") continue;
    const g = byId.get(n.parent!)!;
    const x = g.hx + n.hx;
    const y = g.hy + n.hy;
    const rows = nodes.filter((m) => m.parent === n.id).length;
    if (n.side === "left" || n.side === "right") {
      halfW = Math.max(halfW, Math.abs(x) + 78 + 185);
      halfH = Math.max(halfH, Math.abs(y) + (rows * ROW_H) / 2 + 10);
    } else {
      halfW = Math.max(halfW, Math.abs(x) + 110);
      halfH = Math.max(halfH, Math.abs(y) + 60 + rows * ROW_H);
    }
  }
  return { halfW, halfH };
}

export type NodeState = "on" | "near" | "off";

export function selectedNodeId(sel: Selection): string {
  if (sel.level === "mod" && sel.modId) return sel.modId;
  if (sel.level === "category" && sel.gameId && sel.category) return categoryNodeId(sel.gameId, sel.category);
  if (sel.level === "game" && sel.gameId) return sel.gameId;
  return CORE_ID;
}

/** Dims everything outside the branch you've jumped into. */
export function computeStates(nodes: LNode[], sel: Selection): Map<string, NodeState> {
  const state = new Map<string, NodeState>();
  for (const n of nodes) {
    if (sel.level === "core" || n.type === "core") {
      state.set(n.id, "on");
      continue;
    }
    const sameGame = n.gameId === sel.gameId;
    const sameCat = sameGame && n.category === sel.category;
    let s: NodeState = "off";
    if (sel.level === "game") s = sameGame ? "on" : "off";
    else if (n.type === "game") s = sameGame ? "on" : "off";
    else if (n.type === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
    else if (sel.level === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
    else s = n.id === sel.modId || (sameCat && n.type === "more") ? "on" : sameCat ? "near" : sameGame ? "near" : "off";
    state.set(n.id, s);
  }
  return state;
}

