const unstageJs = (js: string) => js.replace(/(["'`(=\s])\/nxm(\/[^"'`\s)<>?#]*)?(?=["'`\s)<>?#$])/g, (m, pre: string, rest?: string) =>
  rest && /\.[a-z0-9]{2,5}$/i.test(rest) ? m : pre + (rest || "/"));

export function PageRuntime({ slug, root = false }: { slug: string; root?: boolean }) {
  useEffect(() => {
    const page = document.querySelector<HTMLElement>(`.nxm-p-${slug}`);
    if (!page) return;
    const root = document.documentElement;
    const rootCls = `nxm-p-${slug}-root`;
    root.classList.add(rootCls);

    // setTimeout: parent (layout) effects — the Aurora mount — run after child
    // effects; the page script must see Aurora already mounted. The guard sits
    // at injection so the script runs exactly once per page load, whatever
    // React does with effects.
    setTimeout(() => {
      SCRIPTS[slug]?.().then(({ PAGE_SCRIPT }) => {
        if (page.dataset.pageMounted || !page.isConnected) return;
        page.dataset.pageMounted = "1";
        const s = document.createElement("script");
        s.textContent = root ? unstageJs(PAGE_SCRIPT) : PAGE_SCRIPT;
        document.body.appendChild(s);
      });
    }, 0);

    return () => {
      root.classList.remove(rootCls);
    };
  }, [slug]);
  return null;
}
