/**
 * The Cyrus entries in the NXM nav (desktop tab, Products menu, mobile sheet)
 * and footer. The nav is the design package's baked HTML, so the entries are
 * injected at render time next to stable anchors, and ONLY for viewers who
 * pass the Cyrus page gate (lib/cyrus/public-gate.ts: Setting
 * cyrus_public_enabled, or a private-preview account). Everyone else gets the
 * nav byte-for-byte unchanged. Launch = the Setting; no code change.
 * Same technique as ./dedicated-nav.ts (and it composes with it: the anchors
 * here are different elements, so either can run first).
 */
import { MARK_ARM, MARK_SWEEP } from "@/components/cyrus/icons/cyrusMark";

/** The Cyrus Y as a one-colour vector (currentColor), squared for a 24px icon box. */
export const CYRUS_Y_SVG = (cls = "nv-ic", size = 24) =>
  `<svg class="${cls}" viewBox="20 -170 940 940" width="${size}" height="${size}" aria-hidden="true" fill="currentColor"><path d="${MARK_SWEEP}"/><path d="${MARK_ARM}"/></svg>`;

const DESKTOP_ANCHOR = '<a class="nv-t nv-labs" href="/nxm/mods">';
const DROPDOWN_ANCHOR = "<span><b>Game Servers</b><small>Minecraft, Rust, Valheim and more</small></span></a>";
const SHEET_ANCHOR = '<a href="/nxm/game-servers">Game Servers</a>';

const DESKTOP = '<a class="nv-t" href="/nxm/cyrus">Cyrus</a>';
const DROPDOWN = `<a class="nv-it" href="/nxm/cyrus">${CYRUS_Y_SVG()}<span><b>Cyrus AI Mod Studio <em class="">New</em></b><small>Describe a mod, Cyrus builds it</small></span></a>`;
const SHEET = '<a href="/nxm/cyrus">Cyrus AI Mod Studio</a>';

export function withCyrusNav(html: string, show: boolean): string {
  if (!show) return html;
  return html
    .replace(DESKTOP_ANCHOR, DESKTOP + DESKTOP_ANCHOR)
    .replace(DROPDOWN_ANCHOR, DROPDOWN_ANCHOR + DROPDOWN)
    .replace(SHEET_ANCHOR, SHEET_ANCHOR + SHEET);
}

/** Footer: the "Game servers" column gets this link, gated exactly like the nav. */
export const CYRUS_FOOTER_COLUMN = "f-games";
export const CYRUS_FOOTER_LINK = { label: "Cyrus AI mod studio", href: "/cyrus" } as const;
export function cyrusFooterLinks<T extends { label: string; href: string }>(columnId: string, links: T[], show: boolean): (T | typeof CYRUS_FOOTER_LINK)[] {
  if (!show || columnId !== CYRUS_FOOTER_COLUMN) return links;
  // after the mod catalogue (the closest relative), else at the end
  const i = links.findIndex((l) => l.href === "/mods");
  const out: (T | typeof CYRUS_FOOTER_LINK)[] = [...links];
  out.splice(i < 0 ? out.length : i + 1, 0, CYRUS_FOOTER_LINK);
  return out;
}

