import "server-only";
import { currentUser } from "@/lib/auth";
import { cyrusPublicEnabled, requireCyrusPageAccess, CYRUS_STUDIO_PATH } from "@/lib/cyrus/public-gate";
import { CATEGORIES, GAMES, MODELS, STARTER_IDEAS } from "@/lib/cyrus/data";
import { CYRUS_DEFAULT_MODEL, CYRUS_MODELS, CYRUS_STAGES } from "@/lib/cyrus/models";
import { cyrusGame, versionRange } from "@/lib/cyrus/games";
import { estimate } from "@/lib/cyrus/estimate";
import { loadTokenConfig, PLAN_TIERS, type PlanTier, type TokenConfig } from "@/lib/cyrus/tokens/config";
import { serverGrant, TIER_LABEL, TIER_MODELS } from "@/lib/cyrus/tokens/economy";
import { planPrices } from "@/lib/cyrus/tokens/billing";
import type { GameSupport } from "@/lib/cyrus/games/support";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, gameTiers, initDisplayFx, usd, type NxmLoad } from "./lib";
import { planCapacity } from "./cyrus-plans";

/**
 * /cyrus: the Cyrus AI mod studio's marketing page (native NXM page,
 * tools/nxm/native/cyrus). GATED: 404 unless lib/cyrus/public-gate.ts passes
 * (Setting cyrus_public_enabled, or a "modbuilder" private-preview account);
 * noindex unless public.
 *
 * Everything shown is read from the system at request time:
 *  - games, categories, models, build stages, starter prompts: lib/cyrus/data.ts,
 *    lib/cyrus/models.ts (the studio's own registry), plus each game's verified
 *    GameSupport file (lib/cyrus/games/<id>.ts) once its agent's branch lands;
 *  - plan prices, tokens, rollover, model unlocks, the pre-build token ranges and
 *    the server-grant rule: the token economy (lib/cyrus/tokens/*, admin Settings,
 *    the real Stripe price when configured), exactly what the studio charges;
 *  - plan estimates ("about N mods or M edits"): ./cyrus-plans.ts over those numbers;
 *  - the cheapest Minecraft server and the tokens it comes with: db.gamePlan + serverGrant().
 * No testimonials, ratings, usage counts or invented stats. Nothing that is not
 * built is described as built: every feature carries its real status.
 */

/** Production hosting page per Cyrus game (all in live-routes.json; test/cyrus-page-gate.test.ts checks). */
export const CYRUS_GAME_HOSTING: Record<string, { family: string; route: string }> = {
  minecraft: { family: "minecraft", route: "/minecraft-server-hosting" },
  palworld: { family: "palworld", route: "/palworld-server-hosting" },
  rust: { family: "rust", route: "/rust-server-hosting" },
  valheim: { family: "valheim", route: "/valheim-server-hosting" },
  zomboid: { family: "projectzomboid", route: "/project-zomboid-server-hosting" },
  terraria: { family: "terraria", route: "/terraria-server-hosting" },
};

/**
 * Minecraft's install facts until a lib/cyrus/games/minecraft.ts GameSupport exists:
 * Cyrus builds Paper/Purpur server plugins (lib/modbuilder/install.ts MB_INSTALL_VARIANTS),
 * which run on the server only; players join with the normal game.
 */
const MINECRAFT_FALLBACK = { side: "server" as const, reason: "Paper plugins run on the server only. Players join with the normal game, nothing to install.", verification: "Compiled against the real Paper API for your exact version, repaired if it fails, then safety-scanned." };

/** A game's verified support file, when its branch has merged (lib/cyrus/games/<id>.ts). */
async function gameSupport(id: string): Promise<GameSupport | null> {
  if (!/^[a-z0-9-]+$/.test(id)) return null;
  try {
    const m = (await import(`../../../lib/cyrus/games/${id}`)) as { default?: GameSupport };
    const s = m.default;
    return s && s.id === id && s.install && s.verification ? s : null;
  } catch {
    return null;
  }
}

const SIDE_LABEL = { server: "Server only", client: "Players install it", both: "Server and players" } as const;

/** The plan price the studio charges: the real Stripe price when configured, else the Setting. */
async function planCents(cfg: TokenConfig): Promise<Record<PlanTier, number>> {
  const prices = await planPrices(cfg).catch(() => ({ katara: null, saka: null, all: null }));
  return Object.fromEntries(PLAN_TIERS.map((t) => [t, prices[t]?.unitAmount ?? cfg.plan.cents[t]])) as Record<PlanTier, number>;
