    const t = "A shop menu with coins, saved balances and a /pay command";
    const a = estimate(t, "saka").usd[1], b = estimate(t, "saka", { change: true }).usd[1];
    return a > 0 ? b / a : 1;
  })();
  const plans = PLAN_TIERS.map((t) => ({ tier: t, name: TIER_LABEL[t], cents: cents[t], tokens: cfg.plan.tokens[t], models: TIER_MODELS[t], cap: planCapacity(cfg.plan.tokens[t], TIER_MODELS[t], cfg.reserve, changeFactor) }));
  const modelName = (id: string) => CYRUS_MODELS.find((m) => m.id === id)?.name ?? id;
  const plansHtml = plans.map((p, i) => {
    const best = p.models[p.models.length - 1];
    const lines = p.cap.map((c) => `<li><span class="cy-pl-m">${icon(`model:${c.model}`, "cy-mg sm")}${esc(modelName(c.model))}</span><span>about <b>${range(c.mods[0], c.mods[1])}</b> typical mods</span><span>or <b>${range(c.edits[0], c.edits[1])}</b> edits</span></li>`).join("");
    return `<li class="cy-plan cy-rv${p.tier === "saka" ? " is-mid" : ""}" style="--d:${i}">` +
      `<div class="cy-plan-h"><b>${esc(p.name)}</b>${p.tier === "saka" ? `<span class="cy-plan-k">Most mods</span>` : ""}</div>` +
      `<p class="cy-plan-p"><span>${usd(p.cents)}</span><small>/month</small></p>` +
      `<p class="cy-plan-t">${icon("coin", "cy-coin")}<b>${p.tokens.toLocaleString("en-US")}</b> tokens every month</p>` +
      `<p class="cy-plan-u">${esc(p.models.map(modelName).join(", "))}</p>` +
      `<ul class="cy-plan-est" aria-label="What ${esc(p.name)} buys, estimated">${lines}</ul>` +
      `<a class="au-btn${p.tier === "saka" ? "" : " au-btn--glass"} cy-plan-go" href="${esc(studio)}">Choose ${esc(p.name)}</a>` +
      `<small class="cy-plan-note">Best with ${esc(modelName(best))}. Tokens roll over for ${plural(cfg.plan.rolloverMonths, "month")}.</small></li>`;
  }).join("");

  // the cheapest Minecraft server, and the tokens it really comes with
  const cheapest = [...mcTiers].sort((a, b) => (a.i ?? a.p) - (b.i ?? b.p))[0] ?? null;
  const grant = cheapest ? serverGrant("initial", Math.round(cheapest.p * 100), 1, cfg) : null;
  const renew = cheapest ? serverGrant("renewal", Math.round(cheapest.p * 100), 1, cfg) : null;
  const grantHtml = cheapest && grant && grant.tokens > 0
    ? `Every paid Minecraft server comes with Cyrus tokens: the ${esc(cheapest.name)} plan (${usd(Math.round(cheapest.p * 100))}/month) includes <b>${grant.tokens.toLocaleString("en-US")}</b>, plus <b>${(renew?.tokens ?? 0).toLocaleString("en-US")}</b> with every renewal. Bigger servers include more, up to ${cfg.grant.initial.max.toLocaleString("en-US")}.`
    : `Every paid Minecraft server comes with Cyrus tokens, between ${cfg.grant.initial.min.toLocaleString("en-US")} and ${cfg.grant.initial.max.toLocaleString("en-US")} depending on the plan.`;
  const topupHtml = cfg.topup.enabled
    ? `Need more in a hurry? Top up from ${usd(cfg.topup.minCents)}: ${cfg.topup.tokensPerUsd.toLocaleString("en-US")} tokens per dollar, usable for ${plural(Math.round(cfg.topup.expiryDays / 30), "month")}.`
    : "";

  // ---- pipeline stages (the studio's own list) ----
  const stagesHtml = CYRUS_STAGES.map((s, i) => `<li style="--d:${i}"><i aria-hidden="true"></i><b>${esc(s.label)}</b><small>${esc(s.sub)}</small></li>`).join("");

  // ---- JSON-LD: the product with its real plan offers ----
  const ld = [{
    "@context": "https://schema.org", "@type": "SoftwareApplication", name: "Cyrus",
    alternateName: "Cyrus AI Mod Studio",
    applicationCategory: "DeveloperApplication", applicationSubCategory: "Game mod builder", operatingSystem: "Web",
    description: `An AI mod studio for game servers: describe a mod and Cyrus plans it, writes the code, compiles it, safety-checks it and installs it on your server. Live for ${liveGames.map((g) => g.name).join(", ")}.`,
    url: APP_URL + "/cyrus",
    publisher: { "@type": "Organization", name: "Nxeon", url: APP_URL },
    offers: {
      "@type": "AggregateOffer", priceCurrency: "USD",
      lowPrice: (Math.min(...plans.map((p) => p.cents)) / 100).toFixed(2), highPrice: (Math.max(...plans.map((p) => p.cents)) / 100).toFixed(2),
      offerCount: plans.length,
      offers: plans.map((p) => ({ "@type": "Offer", name: `Cyrus ${p.name} plan`, price: (p.cents / 100).toFixed(2), priceCurrency: "USD", url: APP_URL + "/cyrus#plans",
        priceSpecification: { "@type": "UnitPriceSpecification", price: (p.cents / 100).toFixed(2), priceCurrency: "USD", unitCode: "MON", referenceQuantity: { "@type": "QuantitativeValue", value: 1, unitCode: "MON" } } })),
    },
    featureList: ["Plain-language mod requests", "Automatic routing to the right game and category", "Compiles and repairs the code", "Static safety scan before you see it", "One-click install on your server with backup and rollback", "Versions, notes and the full source"],
  }];

  // what the demo needs (client-safe, no prices)
  const data = {
    games: games.map(({ id, name, short, rgb, logo, logoTone, status, categories, aliases }) => ({ id, name, short, rgb, logo, logoTone, status, categories, aliases })),
    categories: CATEGORIES.map(({ key, label, rgb, keywords }) => ({ key, label, rgb, keywords })),
    models: CYRUS_MODELS.map((m) => ({ id: m.id, name: m.name, blurb: m.blurb, rgb: meta3[m.id]?.rgb ?? "167 139 250" })),
    defaultModel: CYRUS_DEFAULT_MODEL,
    reserve: cfg.reserve,
    stages: CYRUS_STAGES,
    starters: STARTER_IDEAS.map(({ label, prompt, gameId }) => ({ label, prompt, gameId })),
    mcVersion: mc.defaultVersion ?? mc.versions[0] ?? "",
  };

  return {
    slots: {
      studio,
      versions,
      liveNames: liveGames.map((g) => g.name).join(", ") || "Minecraft",
      soonCount: String(games.length - liveGames.length),
      gameCount: String(games.length),
      "heroGames:html": games.map((g, i) => `<li class="cy-hg${g.status === "live" ? " is-live" : ""}" style="--g:${g.rgb};--i:${i}"><span class="cy-logo${g.logoTone === "light" ? " is-light" : ""}">${g.logo ? `<img src="${esc(g.logo)}" alt="" width="44" height="44" decoding="async">` : ""}</span><span class="cy-hg-n">${esc(g.short)}</span><span class="cy-hg-s">${g.status === "live" ? "Live" : "Soon"}</span></li>`).join(""),
      "games:html": gamesHtml,
      "models:html": modelsHtml,
      "plans:html": plansHtml,
      "stages:html": stagesHtml,
      "grant:html": grantHtml,
      topup: topupHtml,
      rollover: plural(cfg.plan.rolloverMonths, "month"),
      minSpend: String(cfg.minSpend),
      freeFailures: String(cfg.freeFailures),
      freeFailuresDays: String(cfg.freeFailuresDays),
    },
    data,
    crumb: "Cyrus AI mod studio",
    jsonLd: ld,
  };
}

