/**
 * "How many mods or edits does a plan buy?" for the Cyrus page (PURE, unit-tested in
 * test/cyrus-page-gate.test.ts). Computed from the REAL token economy, never typed in:
 *  - a plan's monthly tokens (Setting cyrus_tok_plan_<tier>_tokens);
 *  - the pre-build token range per model and size (Setting cyrus_tok_reserve_table,
 *    [typical low, high]; the high end is what a build reserves);
 *  - the studio's change-request factor (lib/cyrus/estimate.ts, passed in by the loader).
 * A range is [tokens / high, tokens / low]: the fewest you get if every build is at the
 * top of its range, and the most if they are all typical-low. Shown as an estimate.
 *
 * NOTE for the merge with feature/cyrus-v6-studio: the studio's plan cards get their own
 * estimator (studio-ui brief item 8). If it lands as a shared helper, switch the loader to it
 * so the page and the studio always print the same numbers.
 */
import type { CyrusModelId } from "@/lib/cyrus/models";
import type { ReserveTable } from "@/lib/cyrus/tokens/config";

export type PlanCapacity = { model: CyrusModelId; mods: [number, number]; small: [number, number]; edits: [number, number] };

const fit = (tokens: number, [lo, hi]: [number, number], k = 1): [number, number] => {
  const a = Math.max(1, hi * k), b = Math.max(1, lo * k);
  return [Math.floor(tokens / a), Math.floor(tokens / b)];
};

export function planCapacity(tokens: number, models: readonly CyrusModelId[], reserve: ReserveTable, changeFactor = 1): PlanCapacity[] {
  const k = Number.isFinite(changeFactor) && changeFactor > 0 ? changeFactor : 1;
  return models.map((model) => {
    const r = reserve[model] ?? reserve.saka;
    return { model, mods: fit(tokens, r.standard), small: fit(tokens, r.simple), edits: fit(tokens, r.simple, k) };
  });
}

