.cy-head .h2{max-width:24ch}
.pg-cy .h2,.pg-cy .faq summary{color:var(--cy-ink)}
.pg-cy .lede{color:var(--cy-ink2)}

/* icons filled in by the client mount (data-cy-icon); sized so nothing shifts */
.cy-ic,.cy-mg{display:inline-flex;align-items:center;justify-content:center;flex:none;width:1.15em;height:1.15em;line-height:0}
.cy-ic svg,.cy-mg svg{width:100%;height:100%}
.cy-mg.sm{width:1.05em;height:1.05em}

/* status pills */
.cy-pill{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:999px;font:600 .68rem var(--f-mono);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
.cy-pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.cy-pill.live{color:var(--cy-live);background:var(--cy-livesoft)}
.cy-pill.dev{color:var(--cy-dev);background:var(--cy-devsoft)}

/* ---------- motion: reveal once ---------- */
@keyframes cy-up{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes cy-draw{from{stroke-dashoffset:var(--len,600)}to{stroke-dashoffset:0}}
@keyframes cy-pop{from{opacity:0;transform:translate(-50%,-50%) scale(.7)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes cy-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes cy-sheen{0%{background-position:160% 0}55%,100%{background-position:-60% 0}}
@keyframes cy-tick{from{transform:scale(.4);opacity:0}to{transform:none;opacity:1}}
@keyframes cy-blink{0%,100%{opacity:1}50%{opacity:.35}}
.cy-anim .cy-rv:not(.in){opacity:0}
.cy-anim .cy-rv.in{animation:cy-up .7s cubic-bezier(.2,.7,.2,1) calc(var(--d,0) * 60ms) backwards}

/* ---------- hero ---------- */
.cy-hero{position:relative;isolation:isolate;padding:calc(var(--nav-h) + clamp(40px,6vw,84px)) 0 clamp(40px,6vw,80px)}
.cy-hero-sky{position:absolute;inset:0;z-index:-1;overflow:hidden;pointer-events:none;
  background:
   radial-gradient(38% 46% at 74% 44%,rgba(139,92,246,.22),transparent 70%),
   radial-gradient(30% 38% at 64% 64%,rgba(34,211,238,.10),transparent 70%),
   radial-gradient(1px 1px at 12% 22%,rgba(255,255,255,.55),transparent 60%),
   radial-gradient(1px 1px at 34% 70%,rgba(255,255,255,.35),transparent 60%),
   radial-gradient(1.2px 1.2px at 58% 18%,rgba(255,255,255,.45),transparent 60%),
   radial-gradient(1px 1px at 88% 30%,rgba(255,255,255,.4),transparent 60%),
   radial-gradient(1px 1px at 92% 78%,rgba(255,255,255,.3),transparent 60%),
   radial-gradient(1px 1px at 22% 88%,rgba(255,255,255,.3),transparent 60%)}
.cy-hero-sky::after{content:"";position:absolute;inset:auto 0 0;height:180px;background:linear-gradient(180deg,transparent,var(--cy-bg))}
.pg-cy[data-cy-theme="light"] .cy-hero-sky{background:radial-gradient(40% 48% at 74% 44%,rgba(139,92,246,.16),transparent 70%),radial-gradient(30% 38% at 62% 66%,rgba(34,211,238,.12),transparent 70%)}
.cy-hero-in{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,1fr);align-items:center;gap:clamp(24px,4vw,64px)}
.cy-kicker{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin:0 0 26px;font:600 .74rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-kicker span{padding-left:14px;border-left:1px solid var(--cy-line2)}
.cy-wm{display:block;height:28px;width:auto}
.cy-wm-l,.cy-coin-l,.cy-badge-l{display:none}
.pg-cy[data-cy-theme="light"] .cy-wm-d,.pg-cy[data-cy-theme="light"] .cy-coin-d,.pg-cy[data-cy-theme="light"] .cy-badge-d{display:none}
.pg-cy[data-cy-theme="light"] .cy-wm-l,.pg-cy[data-cy-theme="light"] .cy-coin-l,.pg-cy[data-cy-theme="light"] .cy-badge-l{display:block}
.cy-h1{margin:0 0 22px;font-size:clamp(2.6rem,5.6vw,4.9rem);line-height:1;letter-spacing:-.045em;font-weight:760;color:var(--cy-ink);text-wrap:balance}
.cy-h1 span{color:var(--cy-accink)}
.cy-lede{margin:0 0 30px;max-width:56ch;color:var(--cy-ink2);font-size:clamp(1.02rem,1.25vw,1.14rem);line-height:1.65}
.cy-ctas{display:flex;flex-wrap:wrap;gap:12px}
.cy-hero-note{margin:22px 0 0;font-size:.86rem;color:var(--cy-ink3)}

.cy-hero-art{position:relative;width:100%;max-width:600px;aspect-ratio:1;margin-inline:auto}
.cy-threads{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.cy-threads path{fill:none;stroke-linecap:round}
.cy-threads .t-glow{stroke-width:6;opacity:.14}
.cy-threads .t-line{stroke-width:1.4;opacity:.75}
.cy-threads .t-soon{stroke-dasharray:2 7;opacity:.45}
.cy-threads .t-dot{opacity:0}
.cy-hero-art.drawn .cy-threads .t-line:not(.t-soon),.cy-hero-art.drawn .cy-threads .t-glow{stroke-dasharray:var(--len) var(--len);animation:cy-draw 1.4s cubic-bezier(.4,.1,.2,1) calc(.25s + var(--i,0) * .09s) backwards}
.cy-coin{position:absolute;left:50%;top:50%;width:54%;aspect-ratio:1;transform:translate(-50%,-50%);perspective:900px;z-index:1}
.cy-coin::before{content:"";position:absolute;left:8%;right:8%;bottom:-10%;height:22%;border-radius:50%;background:radial-gradient(50% 50% at 50% 50%,rgba(139,92,246,.45),transparent 70%);filter:blur(10px);z-index:-1}
.pg-cy[data-cy-theme="light"] .cy-coin::before{background:radial-gradient(50% 50% at 50% 50%,rgba(90,70,190,.22),transparent 70%)}
.cy-coin-tilt{position:relative;width:100%;height:100%;transform:rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transform-style:preserve-3d;transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.cy-coin-img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 26px 40px rgba(40,10,120,.45))}
.pg-cy[data-cy-theme="light"] .cy-coin-img{filter:drop-shadow(0 22px 34px rgba(60,40,140,.22))}
.cy-coin-sheen{position:absolute;inset:0;pointer-events:none;background:linear-gradient(105deg,transparent 38%,rgba(255,255,255,.55) 49%,rgba(255,255,255,.08) 54%,transparent 62%) no-repeat;background-size:220% 100%;background-position:160% 0;mix-blend-mode:soft-light;
  -webkit-mask:url(/cyrus/marketing/coin-dark-sm.webp) center/contain no-repeat;mask:url(/cyrus/marketing/coin-dark-sm.webp) center/contain no-repeat}
.pg-cy[data-cy-theme="light"] .cy-coin-sheen{-webkit-mask-image:url(/cyrus/marketing/coin-light.webp);mask-image:url(/cyrus/marketing/coin-light.webp);mix-blend-mode:overlay}
.cy-hgames{position:absolute;inset:0;margin:0;padding:0;list-style:none;z-index:2}
.cy-hg{position:absolute;display:flex;flex-direction:column;align-items:center;gap:5px;transform:translate(-50%,-50%);font-size:.74rem;color:var(--cy-ink2);white-space:nowrap}
.cy-hg:nth-child(1){left:30%;top:14%}.cy-hg:nth-child(2){left:70%;top:14%}.cy-hg:nth-child(3){left:91%;top:50%}
.cy-hg:nth-child(4){left:72%;top:85%}.cy-hg:nth-child(5){left:28%;top:85%}.cy-hg:nth-child(6){left:9%;top:50%}
.cy-hg .cy-logo{width:46px;height:46px}
.cy-hg-n{font-weight:650;color:var(--cy-ink)}
.cy-hg-s{font:600 .58rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-hg.is-live .cy-hg-s{color:var(--cy-live)}
.cy-hero-art.drawn .cy-hg{animation:cy-pop .6s cubic-bezier(.2,.8,.2,1.2) calc(.9s + var(--i,0) * .09s) backwards}
.cy-logo{position:relative;display:inline-flex;align-items:center;justify-content:center;flex:none;border-radius:50%;overflow:hidden;background:#0b0a18;box-shadow:0 0 0 1.5px rgb(var(--g,167 139 250) / .7),0 0 18px -2px rgb(var(--g,167 139 250) / .55)}
.cy-logo img{width:100%;height:100%;object-fit:cover;border-radius:50%}
.pg-cy[data-cy-theme="light"] .cy-logo{background:#fff;box-shadow:0 0 0 1.5px rgb(var(--g,109 74 224) / .75),0 6px 16px -8px rgb(var(--g,109 74 224) / .6)}
.pg-cy[data-cy-theme="light"] .cy-logo.is-light img{filter:brightness(.25)}
.cy-theme{position:absolute;top:calc(var(--nav-h) + 18px);right:clamp(20px,4vw,40px);display:inline-flex;align-items:center;gap:8px;height:34px;padding:0 14px 0 10px;border-radius:999px;border:1px solid var(--cy-line2);background:color-mix(in srgb,var(--cy-card) 80%,transparent);color:var(--cy-ink2);font:600 .76rem var(--f-body);cursor:pointer;z-index:3}
.cy-theme:hover{color:var(--cy-ink);border-color:var(--cy-line3)}
.cy-theme:focus-visible{outline:2px solid var(--cy-acc);outline-offset:2px}
.cy-theme-i{width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 70% 30%,transparent 42%,currentColor 44%)}
.pg-cy[data-cy-theme="light"] .cy-theme-i{background:radial-gradient(circle,currentColor 38%,transparent 40%),conic-gradient(from 0deg,currentColor 0 4%,transparent 4% 12.5%,currentColor 12.5% 16.5%,transparent 16.5% 25%,currentColor 25% 29%,transparent 29% 37.5%,currentColor 37.5% 41.5%,transparent 41.5% 50%,currentColor 50% 54%,transparent 54% 62.5%,currentColor 62.5% 66.5%,transparent 66.5% 75%,currentColor 75% 79%,transparent 79% 87.5%,currentColor 87.5% 91.5%,transparent 91.5%);-webkit-mask:radial-gradient(circle,#000 70%,transparent 71%);mask:radial-gradient(circle,#000 70%,transparent 71%)}
@media (prefers-reduced-motion:no-preference){
  .cy-coin-sheen{animation:cy-sheen 9s ease-in-out 1.6s infinite}
  .cy-final-coin{animation:cy-float 6s ease-in-out infinite}
}

/* ---------- live demo (React island: components/cyrus/marketing/CyrusDemo.tsx) ---------- */
.cy-demo-flag{display:flex;gap:10px;align-items:baseline;max-width:340px;margin:0;font-size:.84rem;line-height:1.5;color:var(--cy-ink3)}
.cy-demo-flag b{flex:none;padding:3px 9px;border-radius:999px;background:var(--cy-accsoft);color:var(--cy-accink);font:700 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase}
.cy-demo{position:relative;border-radius:28px;border:1px solid var(--cy-line2);background:var(--cy-stage);box-shadow:var(--cy-shadow);overflow:hidden;min-height:clamp(560px,62vw,760px)}
.cy-demo-fallback{display:grid;place-items:center;min-height:inherit;padding:32px;text-align:center;color:var(--cy-ink3)}
.cy-demo.on .cy-demo-fallback{display:none}
.cyd{position:relative;display:grid;grid-template-rows:minmax(0,1fr) auto;min-height:inherit}
.cyd-stage{position:relative;min-height:clamp(380px,44vw,560px);overflow:hidden;touch-action:pan-y;cursor:default}
.cyd-canvas,.cyd-core{position:absolute;left:0;top:0;pointer-events:none}
.cyd-core{will-change:transform}
.cyd-nodes{position:absolute;inset:0}
.cyd-node{position:absolute;left:0;top:0;will-change:transform;transition:opacity .45s ease}
.cyd-node.off{opacity:.22}
.cyd-game{display:flex;flex-direction:column;align-items:center;gap:6px;transform:translate(-50%,-50%)}
.cyd-game button{all:unset;cursor:pointer;border-radius:50%}
.cyd-game button:focus-visible{outline:2px solid var(--cy-acc);outline-offset:4px}
.cyd-game .cy-logo{width:var(--sz,64px);height:var(--sz,64px);transition:box-shadow .3s ease,transform .3s ease}
.cyd-game.hit .cy-logo{transform:scale(1.08);box-shadow:0 0 0 2px rgb(var(--g)),0 0 32px 2px rgb(var(--g) / .8)}
.cyd-gname{padding:2px 9px;border-radius:999px;background:rgba(6,4,18,.72);border:1px solid rgb(var(--g) / .35);font:650 .72rem var(--f-body);color:#f2eeff;white-space:nowrap}
.cyd-gname em{margin-left:6px;font:600 .56rem var(--f-mono);font-style:normal;letter-spacing:.1em;text-transform:uppercase;color:rgba(242,238,255,.55)}
.cyd-gname em.live{color:#67e8f9}
.cyd-cat{display:flex;align-items:center;gap:8px;transform:translate(-50%,-50%)}
.cyd-cat[data-side="left"]{flex-direction:row-reverse}
.cyd-corb{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:rgba(8,6,22,.85);color:rgb(var(--g));box-shadow:0 0 0 1px rgb(var(--g) / .55),0 0 14px -2px rgb(var(--g) / .5);font-size:17px;transition:box-shadow .3s,transform .3s}
.cyd-cat.hit .cyd-corb{transform:scale(1.12);box-shadow:0 0 0 1.5px rgb(var(--g)),0 0 24px 2px rgb(var(--g) / .75)}
.cyd-clabel{font:600 .7rem var(--f-body);color:rgba(242,238,255,.82);white-space:nowrap}
.cyd-pill{display:flex;align-items:center;gap:7px;height:28px;padding:0 12px 0 9px;border-radius:999px;background:rgba(8,6,22,.9);border:1px solid rgb(var(--g) / .6);box-shadow:0 0 20px -4px rgb(var(--g) / .7);font:650 .74rem var(--f-body);color:#fff;white-space:nowrap;transform:translate(0,-50%)}
.cyd-pill[data-side="left"]{transform:translate(-100%,-50%)}
.cyd-pill i{width:8px;height:8px;border-radius:2px;background:rgb(var(--g));box-shadow:0 0 8px rgb(var(--g))}
.cyd-pill.forging i{animation:cy-blink .8s ease-in-out infinite}
.cyd-pill small{font:600 .58rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:rgba(242,238,255,.55)}
.cyd-corelabel{transform:translate(-50%,0);display:flex;align-items:center;gap:6px;font:600 .62rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(242,238,255,.6);white-space:nowrap}
.cyd-corelabel i{width:6px;height:6px;border-radius:50%;background:#67e8f9;box-shadow:0 0 8px #67e8f9}
.pg-cy[data-cy-theme="light"] .cyd-gname{background:rgba(255,255,255,.9);color:#16122e}
.pg-cy[data-cy-theme="light"] .cyd-gname em{color:#6b6690}.pg-cy[data-cy-theme="light"] .cyd-gname em.live{color:#0e7490}
.pg-cy[data-cy-theme="light"] .cyd-corb{background:#fff}
.pg-cy[data-cy-theme="light"] .cyd-clabel{color:#2c2650}
.pg-cy[data-cy-theme="light"] .cyd-pill{background:#fff;color:#16122e}
.pg-cy[data-cy-theme="light"] .cyd-pill small{color:#6b6690}
.pg-cy[data-cy-theme="light"] .cyd-corelabel{color:#6b6690}

/* the result card */
.cyd-card{position:absolute;right:18px;top:18px;width:min(340px,calc(100% - 36px));max-height:calc(100% - 36px);overflow:auto;padding:18px;border-radius:20px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow);color:var(--cy-ink);transition:opacity .35s ease,transform .35s ease;z-index:3}
.cyd-card[hidden]{display:block;opacity:0;transform:translateY(8px);pointer-events:none}
.cyd-card-k{display:flex;align-items:center;gap:8px;margin:0 0 4px;font:600 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cyd-card h3{margin:0 0 4px;font-size:1.12rem;letter-spacing:-.01em}
.cyd-card p{margin:0 0 12px;font-size:.84rem;line-height:1.5;color:var(--cy-ink2)}
.cyd-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 14px}
.cyd-facts div{padding:8px 10px;border-radius:12px;background:var(--cy-card2);border:1px solid var(--cy-line)}
.cyd-facts dt{font:600 .58rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cyd-facts dd{margin:3px 0 0;display:flex;align-items:center;gap:6px;font-size:.84rem;font-weight:650}
.cyd-steps{display:grid;gap:6px;margin:0 0 12px;padding:0;list-style:none}
.cyd-steps li{display:grid;grid-template-columns:18px 1fr auto;align-items:center;gap:8px;font-size:.8rem;color:var(--cy-ink3)}
.cyd-steps li i{width:14px;height:14px;border-radius:50%;border:1.5px solid var(--cy-line3)}
.cyd-steps li.on{color:var(--cy-ink)}
.cyd-steps li.on i{border-color:var(--cy-acc);box-shadow:inset 0 0 0 3px var(--cy-card),inset 0 0 0 8px var(--cy-acc);animation:cy-blink 1s ease-in-out infinite}
.cyd-steps li.done{color:var(--cy-ink2)}
.cyd-steps li.done i{border-color:var(--cy-live);background:var(--cy-live);box-shadow:inset 0 0 0 3px var(--cy-card)}
.cyd-steps li.skip{opacity:.55}
.cyd-steps small{font:500 .64rem var(--f-mono);color:var(--cy-ink3)}
.cyd-code{margin:0 0 10px;padding:10px 12px;border-radius:12px;background:var(--cy-deep);border:1px solid var(--cy-line);font:500 .7rem/1.6 var(--f-mono);color:var(--cy-ink2);white-space:pre;overflow:auto}
.cyd-note{display:block;font-size:.74rem;line-height:1.45;color:var(--cy-ink3)}
.cyd-note.soon{color:var(--cy-dev)}
.cyd-x{position:absolute;right:10px;top:10px;width:28px;height:28px;border-radius:50%;border:0;background:var(--cy-card2);color:var(--cy-ink2);cursor:pointer;font-size:14px;line-height:28px}
.cyd-x:focus-visible{outline:2px solid var(--cy-acc)}

/* the prompt dock (mirrors the studio's) */
.cyd-dockwrap{position:relative;z-index:4;padding:0 clamp(12px,2vw,22px) clamp(14px,2vw,22px)}
.cyd-dock{max-width:860px;margin:0 auto;padding:12px 12px 10px;border-radius:20px;background:color-mix(in srgb,var(--cy-card) 94%,transparent);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow)}
.cyd-route{display:flex;align-items:center;gap:8px;min-height:24px;margin:0 0 8px;padding:0 4px;font:600 .7rem var(--f-mono);letter-spacing:.04em;color:var(--cy-ink3)}
.cyd-route b{color:var(--cy-accink);font-weight:650}
.cyd-route i{width:6px;height:6px;border-radius:50%;background:var(--cy-acc);box-shadow:0 0 8px var(--cy-acc)}
.cyd-in{display:block;width:100%;min-height:52px;max-height:120px;padding:8px 6px;border:0;outline:0;resize:none;background:transparent;color:var(--cy-ink);font:500 1rem/1.5 var(--f-body)}
.cyd-in::placeholder{color:var(--cy-ink3)}
.cyd-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding-top:8px;border-top:1px solid var(--cy-line)}
.cyd-models{display:inline-flex;padding:3px;border-radius:12px;background:var(--cy-card2);border:1px solid var(--cy-line)}
.cyd-models button{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 10px;border:0;border-radius:9px;background:none;color:var(--cy-ink3);font:600 .78rem var(--f-body);cursor:pointer}
.cyd-models button[aria-pressed="true"]{background:var(--cy-card3);color:var(--cy-ink);box-shadow:0 0 0 1px rgb(var(--m) / .55)}
.cyd-models button .cy-mg{color:rgb(var(--m))}
.cyd-models button:focus-visible{outline:2px solid var(--cy-acc);outline-offset:1px}
.cyd-est{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3);white-space:nowrap}
.cyd-est b{color:var(--cy-ink2);font-weight:600}
.cyd-go{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 16px;border:0;border-radius:11px;background:var(--cy-acc2);color:#fff;font:700 .84rem var(--f-body);cursor:pointer}
.cyd-go:disabled{opacity:.5;cursor:default}
.cyd-go:focus-visible{outline:2px solid var(--cy-ink);outline-offset:2px}
.cyd-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;max-width:860px;margin:12px auto 0}
.cyd-chips span{font:600 .64rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3);align-self:center}
.cyd-chips button{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 12px 0 6px;border-radius:999px;border:1px solid var(--cy-line2);background:var(--cy-card);color:var(--cy-ink2);font:600 .78rem var(--f-body);cursor:pointer}
.cyd-chips button:hover{color:var(--cy-ink);border-color:var(--cy-line3)}
.cyd-chips button:focus-visible{outline:2px solid var(--cy-acc)}
.cyd-chips .cy-logo{width:22px;height:22px;box-shadow:0 0 0 1px rgb(var(--g) / .7)}
.cyd-clarify{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
.cyd-clarify button{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px 0 4px;border-radius:999px;border:1px solid var(--cy-line2);background:var(--cy-card2);color:var(--cy-ink);font:600 .74rem var(--f-body);cursor:pointer}
.cyd-clarify .cy-logo{width:20px;height:20px}

/* ---------- the flow ---------- */
.cy-flow{position:relative;margin:0;padding:0;list-style:none;counter-reset:s}
.cy-flow::before{content:"";position:absolute;left:21px;top:30px;bottom:30px;width:1px;background:linear-gradient(180deg,var(--cy-line2),var(--cy-line) 85%,transparent)}
.cy-step{position:relative;display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:clamp(24px,4vw,64px);min-height:min(74vh,640px);align-items:start;padding:clamp(18px,3vw,28px) 0}
.cy-step-t{position:relative;padding-left:64px;padding-top:clamp(12px,6vh,64px)}
.cy-step-n{position:absolute;left:0;top:clamp(8px,6vh,60px);display:grid;place-items:center;width:43px;height:43px;border-radius:50%;background:var(--cy-bg);border:1px solid var(--cy-line2);font:600 .78rem var(--f-mono);color:var(--cy-ink3);transition:all .4s ease}
.cy-step.on .cy-step-n{border-color:var(--cy-acc);color:var(--cy-ink);box-shadow:0 0 0 4px var(--cy-accsoft),0 0 22px -4px var(--cy-acc)}
.cy-step h3{display:inline;margin:0 12px 0 0;font-size:clamp(1.35rem,2.2vw,1.8rem);letter-spacing:-.02em;color:var(--cy-ink)}
.cy-step-t .cy-pill{vertical-align:4px}
.cy-step-t p{margin:14px 0 0;max-width:46ch;color:var(--cy-ink2);line-height:1.65}
.cy-step-v{position:sticky;top:calc(var(--nav-h) + 48px)}
.cy-v{position:relative;padding:clamp(18px,2.4vw,26px);border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow);transition:transform .6s cubic-bezier(.2,.7,.2,1),opacity .6s ease}
.cy-anim .cy-step:not(.seen) .cy-v{opacity:.35;transform:translateY(14px) scale(.985)}
.cy-v-cap{margin:14px 0 0;font:600 .6rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--cy-ink3)}
/* 1 dock */
.cy-dock-in{min-height:84px;padding:4px 2px 14px;font-size:1.02rem;line-height:1.55;color:var(--cy-ink)}
.cy-dock-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:12px;border-top:1px solid var(--cy-line)}
.cy-chip{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px;border-radius:9px;background:var(--cy-card2);border:1px solid var(--cy-line2);font:600 .78rem var(--f-body);color:var(--cy-ink)}
.cy-chip .cy-mg{color:#818cf8}
.cy-dock-est{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-dock-go{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--cy-acc2);color:#fff;font-weight:800}
/* 2 route */
.cy-v-route{min-height:220px}
.cy-v-route svg{position:absolute;inset:26px 26px auto;width:calc(100% - 52px);height:150px}
.cy-route-l{fill:none;stroke:var(--cy-acc);stroke-width:2;stroke-dasharray:4 7;opacity:.75}
.cy-step.on .cy-route-l{animation:cy-dash 1.2s linear infinite}
@keyframes cy-dash{to{stroke-dashoffset:-22}}
.cy-rn{position:absolute;display:inline-flex;align-items:center;height:28px;padding:0 11px;border-radius:999px;background:var(--cy-card2);border:1px solid var(--cy-line2);font:650 .76rem var(--f-body);color:var(--cy-ink);transform:translate(-50%,-50%);white-space:nowrap}
.cy-rn.core{left:calc(26px + (100% - 52px) * .11);top:calc(26px + 75px);border-color:var(--cy-acc)}
.cy-rn.game{left:calc(26px + (100% - 52px) * .39);top:calc(26px + 40px);border-color:rgb(52 211 153 / .7)}
.cy-rn.cat{left:calc(26px + (100% - 52px) * .66);top:calc(26px + 75px);border-color:rgb(251 113 133 / .7)}
.cy-rn.mod{left:calc(26px + (100% - 52px) * .86);top:calc(26px + 110px);border-color:rgb(251 113 133 / .9);box-shadow:0 0 18px -6px rgb(251 113 133)}
.cy-route-chip{position:absolute;left:26px;right:26px;bottom:22px;margin:0;display:flex;align-items:center;gap:8px;font:600 .74rem var(--f-mono);color:var(--cy-accink)}
.cy-route-chip::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--cy-acc);box-shadow:0 0 8px var(--cy-acc)}
/* 3 stages */
.cy-stages{display:grid;gap:4px;margin:0;padding:0;list-style:none}
.cy-stages li{display:grid;grid-template-columns:22px auto 1fr;align-items:center;gap:12px;padding:10px 4px;border-bottom:1px solid var(--cy-line)}
.cy-stages li:last-child{border-bottom:0}
.cy-stages i{width:16px;height:16px;border-radius:50%;border:1.5px solid var(--cy-line3)}
.cy-stages b{font-size:.94rem;color:var(--cy-ink)}
.cy-stages small{justify-self:end;font:500 .72rem var(--f-mono);color:var(--cy-ink3);text-align:right}
.cy-step.on .cy-stages i{animation:cy-tick .4s cubic-bezier(.2,.8,.2,1.3) calc(.25s + var(--d) * .32s) both;border-color:var(--cy-live);background:radial-gradient(circle,var(--cy-live) 38%,transparent 42%)}
/* 4 code */
.cy-tabs{display:flex;flex-wrap:wrap;gap:4px;margin:0 0 12px}
.cy-tabs span{padding:5px 10px;border-radius:8px;font:600 .74rem var(--f-body);color:var(--cy-ink3)}
.cy-tabs span.on{background:var(--cy-accsoft);color:var(--cy-ink)}
.cy-code{margin:0;padding:14px 16px;border-radius:14px;background:var(--cy-deep);border:1px solid var(--cy-line);font:500 .78rem/1.65 var(--f-mono);color:var(--cy-ink2);overflow:auto}
.cy-code b{color:var(--cy-accink);font-weight:600}
.cy-vers{display:grid;gap:6px;margin:12px 0 0;padding:0;list-style:none;font-size:.84rem;color:var(--cy-ink2)}
.cy-vers li{display:flex;gap:10px;align-items:baseline}
.cy-vers b{font:600 .72rem var(--f-mono);color:var(--cy-live)}
/* 5 page */
.cy-page-h{display:flex;align-items:center;gap:12px;margin:0 0 10px}
.cy-page-h b{display:block;font-size:1.06rem;color:var(--cy-ink)}
.cy-page-h small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-page-ic{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:rgba(251,113,133,.12);color:#fb7185;font-size:22px;box-shadow:0 0 0 1px rgba(251,113,133,.4)}
.cy-v-page>p{margin:0 0 14px;color:var(--cy-ink2);font-size:.92rem}
.cy-page-f{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}
.cy-page-f img{height:44px;width:auto}
.cy-btnlike{display:inline-flex;align-items:center;height:34px;padding:0 14px;border-radius:10px;border:1px solid var(--cy-line3);font:650 .8rem var(--f-body);color:var(--cy-ink)}
/* 6 tree */
.cy-v-tree{padding-bottom:20px}
.cy-tree-o,.cy-v-tree li{display:flex;flex-direction:column;padding:12px 14px;border-radius:14px;background:var(--cy-card2);border:1px solid var(--cy-line2)}
.cy-tree-o{border-color:var(--cy-acc)}
.cy-tree-o b,.cy-v-tree li b{font-size:.92rem;color:var(--cy-ink)}
.cy-tree-o small,.cy-v-tree li small{font:500 .7rem var(--f-mono);color:var(--cy-ink3)}
.cy-v-tree ul{position:relative;display:grid;gap:10px;margin:14px 0 0 26px;padding:0 0 0 18px;list-style:none;border-left:1px dashed var(--cy-line3)}
.cy-v-tree li{position:relative}
.cy-v-tree li::before{content:"";position:absolute;left:-19px;top:50%;width:18px;border-top:1px dashed var(--cy-line3)}
/* 7 install */
.cy-srv{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:var(--cy-card2);border:1px solid var(--cy-line2);margin:0 0 14px}
.cy-srv b{color:var(--cy-ink)}.cy-srv small{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-srv-dot{width:8px;height:8px;border-radius:50%;background:#34e3a2;box-shadow:0 0 8px #34e3a2}
.cy-checks{display:grid;gap:10px;margin:0;padding:0;list-style:none}
.cy-checks li{display:flex;align-items:center;gap:10px;font-size:.92rem;color:var(--cy-ink2)}
.cy-checks li::before{content:"";flex:none;width:18px;height:18px;border-radius:50%;background:var(--cy-livesoft);box-shadow:inset 0 0 0 1.5px var(--cy-live);-webkit-mask:none}
.cy-step.on .cy-checks li::before{background:radial-gradient(circle,var(--cy-live) 34%,var(--cy-livesoft) 38%)}
/* 8 + install panel: mod rows */
.cy-modrow{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid var(--cy-line)}
.cy-modrow:last-of-type{border-bottom:0}
.cy-modrow b{display:block;font-size:.92rem;color:var(--cy-ink)}
.cy-modrow small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-tog{position:relative;width:34px;height:20px;border-radius:999px;background:var(--cy-card3);box-shadow:inset 0 0 0 1px var(--cy-line2)}
.cy-tog::after{content:"";position:absolute;left:3px;top:3px;width:14px;height:14px;border-radius:50%;background:var(--cy-ink3);transition:transform .3s}
.cy-tog.on{background:color-mix(in srgb,var(--cy-acc) 55%,transparent)}
.cy-tog.on::after{transform:translateX(14px);background:#fff}
.cy-upd{padding:4px 10px;border-radius:8px;background:var(--cy-accsoft);font:600 .72rem var(--f-body);color:var(--cy-accink);white-space:nowrap}
.cy-modrow.warn small{color:var(--cy-dev)}
.cy-warn-i{display:grid;place-items:center;width:20px;height:20px;border-radius:6px;background:var(--cy-devsoft);color:var(--cy-dev);font:800 .8rem var(--f-mono)}

/* ---------- games ---------- */
.cy-games{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:0;padding:0;list-style:none}
.cy-game{position:relative;display:flex;flex-direction:column;gap:12px;padding:22px 22px 20px 26px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);overflow:hidden}
.cy-game::before{content:"";position:absolute;left:0;top:18px;bottom:18px;width:3px;border-radius:0 3px 3px 0;background:rgb(var(--g));box-shadow:0 0 16px rgb(var(--g) / .7)}
.cy-game.is-live{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:40px;padding:28px 30px 26px 34px;border-color:rgb(var(--g) / .45);background:linear-gradient(110deg,rgb(var(--g) / .08),transparent 46%),var(--cy-card)}
.cy-game.is-live>*{grid-column:1}
.cy-game.is-live .cy-game-f,.cy-game.is-live .cy-game-why,.cy-game.is-live .cy-game-cats{grid-column:2}
.cy-game.is-live .cy-game-f{grid-row:1/span 2}
.cy-game-head{display:flex;align-items:center;gap:14px}
.cy-game-head .cy-logo{width:52px;height:52px}
.cy-game.is-live .cy-game-head .cy-logo{width:64px;height:64px}
.cy-game-t{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px}
.cy-game-t b{font-size:1.16rem;letter-spacing:-.01em;color:var(--cy-ink)}
.cy-game.is-live .cy-game-t b{font-size:1.5rem}
.cy-status{display:inline-flex;align-items:center;gap:6px;font:600 .64rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-status::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.cy-status.live{color:var(--cy-live)}
.cy-game-b{margin:0;color:var(--cy-ink2);font-size:.94rem}
.cy-game-f{display:grid;gap:8px;margin:0}
.cy-game-f div{display:grid;grid-template-columns:90px minmax(0,1fr);gap:12px;align-items:baseline}
.cy-game-f dt{font:600 .62rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-game-f dd{margin:0;font-size:.9rem;color:var(--cy-ink)}
.cy-game-why{margin:0;font-size:.86rem;line-height:1.55;color:var(--cy-ink3)}
.cy-game-cats{display:flex;flex-wrap:wrap;gap:6px;margin:0;padding:0;list-style:none}
.cy-game-cats li{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px 0 8px;border-radius:9px;background:var(--cy-card2);border:1px solid var(--cy-line);font:600 .76rem var(--f-body);color:var(--cy-ink2)}
.cy-game-cats li .cy-ic{color:rgb(var(--c));font-size:15px}
.cy-game-go{margin-top:auto;align-self:flex-start;font:650 .84rem var(--f-body);color:var(--cy-accink);text-decoration:none}
.cy-game-go:hover{text-decoration:underline}
.cy-game.is-live .cy-game-go{grid-column:1}

/* ---------- models + plans ---------- */
.cy-models{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0 0 20px;padding:0;list-style:none}
.cy-model{position:relative;display:flex;flex-direction:column;gap:6px;padding:22px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2)}
.cy-model-g{display:grid;place-items:center;width:56px;height:56px;margin:0 0 8px;border-radius:18px;background:rgb(var(--m) / .12);color:rgb(var(--m));box-shadow:0 0 0 1px rgb(var(--m) / .4),0 0 30px -10px rgb(var(--m));font-size:30px}
.cy-model-n{font-size:1.3rem;letter-spacing:-.015em;color:var(--cy-ink)}
.cy-model-tag{font:600 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-model p{margin:6px 0 4px;color:var(--cy-ink2);font-size:.92rem}
.cy-meter{display:flex;gap:4px;margin:2px 0 10px}
.cy-meter i{width:22px;height:5px;border-radius:3px;background:var(--cy-line2)}
.cy-meter i.on{background:rgb(var(--m))}
.cy-model-f{display:grid;gap:6px;margin:0 0 12px;padding:12px 0 0;border-top:1px solid var(--cy-line)}
.cy-model-f div{display:flex;justify-content:space-between;gap:12px}
.cy-model-f dt{font-size:.84rem;color:var(--cy-ink3)}
.cy-model-f dd{margin:0;font:600 .8rem var(--f-mono);color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-model-u{margin-top:auto;font-size:.8rem;color:var(--cy-accink)}
.cy-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0;padding:0;list-style:none}
.cy-plan{display:flex;flex-direction:column;padding:24px;border-radius:24px;background:var(--cy-card);border:1px solid var(--cy-line2)}
.cy-plan.is-mid{border-color:var(--cy-acc);box-shadow:0 0 0 1px var(--cy-acc) inset,0 30px 80px -40px rgba(139,92,246,.6)}
.cy-plan-h{display:flex;align-items:center;justify-content:space-between;gap:10px}
.cy-plan-h b{font-size:1.14rem;color:var(--cy-ink)}
.cy-plan-k{padding:3px 9px;border-radius:999px;background:var(--cy-accsoft);font:600 .62rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--cy-accink)}
.cy-plan-p{margin:14px 0 4px;display:flex;align-items:baseline;gap:4px}
.cy-plan-p span{font-size:2.3rem;font-weight:800;letter-spacing:-.035em;color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-plan-p small{color:var(--cy-ink3)}
.cy-plan-t{display:flex;align-items:center;gap:8px;margin:0 0 4px;color:var(--cy-ink2)}
.cy-plan-t b{color:var(--cy-ink)}
.cy-coin{}
.cy-plan-t .cy-coin,.cy-plan-t i[data-cy-icon="coin"]{width:20px;height:20px;position:static;transform:none;perspective:none;border-radius:50%;background:url(/cyrus/marketing/token-coin.webp) center/cover}
.cy-plan-u{margin:0 0 16px;font-size:.84rem;color:var(--cy-ink3)}
.cy-plan-est{display:grid;gap:10px;margin:0 0 20px;padding:14px 0 0;list-style:none;border-top:1px solid var(--cy-line)}
.cy-plan-est li{display:grid;grid-template-columns:minmax(0,auto) 1fr;gap:2px 12px;font-size:.84rem;color:var(--cy-ink2)}
.cy-plan-est li>span:nth-child(3){grid-column:2}
.cy-pl-m{display:inline-flex;align-items:center;gap:6px;grid-row:span 2;font-weight:650;color:var(--cy-ink)}
.cy-plan-est b{color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-plan-go{margin-top:auto;justify-content:center}
.cy-plan-note{display:block;margin-top:12px;font-size:.76rem;color:var(--cy-ink3)}
.cy-plan-foot{display:grid;gap:8px;max-width:820px;margin:26px auto 0;text-align:center;color:var(--cy-ink2);font-size:.94rem}
.cy-plan-foot p{margin:0}.cy-plan-foot p:empty{display:none}
.cy-plan-foot b{color:var(--cy-ink)}
.cy-fine{font-size:.8rem;color:var(--cy-ink3)}

/* ---------- community ---------- */
.cy-com{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.cy-ticks{display:grid;gap:14px;margin:26px 0 0;padding:0;list-style:none}
.cy-ticks li{position:relative;padding-left:28px;color:var(--cy-ink2);line-height:1.6}
.cy-ticks li::before{content:"";position:absolute;left:0;top:.45em;width:14px;height:14px;border-radius:5px;background:var(--cy-accsoft);box-shadow:inset 0 0 0 1.5px var(--cy-acc)}
.cy-ticks b{color:var(--cy-ink)}
.cy-badges{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.cy-badge{margin:0;display:flex;flex-direction:column;align-items:center;gap:12px;padding:22px 18px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);text-align:center}
.cy-badge img{width:auto;max-width:100%;object-fit:contain}
.cy-badge.b-pill{grid-column:1/-1}
.cy-badge.b-pill img{height:clamp(64px,8vw,96px)}
.cy-badge.b-laurel img{height:clamp(110px,12vw,150px)}
.cy-badge.b-shield img{height:clamp(110px,12vw,150px)}
.cy-badge figcaption{display:grid;gap:4px;font-size:.84rem;line-height:1.5;color:var(--cy-ink3);max-width:30ch}
.cy-badge figcaption b{font-size:.94rem;color:var(--cy-ink)}

/* ---------- install ---------- */
.cy-inst{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.cy-panel{padding:18px 20px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow)}
.cy-panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:0 4px 12px;border-bottom:1px solid var(--cy-line)}
.cy-panel-h b{font-size:1.02rem;color:var(--cy-ink)}
.cy-panel-h small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}

/* ---------- final ---------- */
.cy-final{padding-block:clamp(96px,12vw,168px)}
.cy-final-coin{display:block;width:64px;height:64px;margin:0 auto 18px}
.pg-cy .cy-final h2,.pg-cy .cy-final p{color:var(--cy-ink)}
.pg-cy .cy-final>div>p:not(.nxm-eyebrow){color:var(--cy-ink2)}

/* light theme: shared design classes that hardcode dark colours */
.pg-cy[data-cy-theme="light"] .faq details{border-color:var(--cy-line2)}
.pg-cy[data-cy-theme="light"] .nxm-glassbtn{color:var(--cy-ink);background:#fff;border-color:var(--cy-line3)}

/* ---------- responsive ---------- */
@media (max-width:1080px){
  .cy-models,.cy-plans{grid-template-columns:minmax(0,1fr)}
  .cy-models{grid-template-columns:repeat(3,minmax(0,1fr))}
  .cy-plans{max-width:560px;margin-inline:auto}
}
@media (max-width:900px){
  .cy-hero-in{grid-template-columns:minmax(0,1fr)}
  .cy-hero-art{order:-1;max-width:440px}
  .cy-theme{top:calc(var(--nav-h) + 10px)}
  .cy-step{grid-template-columns:minmax(0,1fr);min-height:0;gap:18px}
  .cy-step-v{position:relative;top:auto;margin-left:64px}
  .cy-step-t,.cy-step-n{padding-top:0;top:0}
  .cy-game.is-live{display:flex}
  .cy-com,.cy-inst{grid-template-columns:minmax(0,1fr)}
  .cy-inst-v{order:2}
  .cyd-card{position:relative;right:auto;top:auto;width:auto;max-height:none;margin:0 12px 12px}
  .cyd-card[hidden]{display:none}
}
@media (max-width:760px){
  .cy-games,.cy-models{grid-template-columns:minmax(0,1fr)}
  .cy-head{margin-bottom:24px}
  .cy-demo{border-radius:22px;margin-inline:-6px}
  .cy-step-v{margin-left:0}
  .cy-flow::before{display:none}
  .cy-step-t{padding-left:56px}
  .cy-step-n{width:40px;height:40px}
  .cy-hg .cy-logo{width:38px;height:38px}
  .cy-hg{font-size:.68rem}
  .cyd-est{margin-left:0;flex-basis:100%;order:-1}
  .cyd-go{margin-left:auto}
  .cyd-models button{padding:0 8px}
  .cy-game{padding:20px 18px 18px 22px}
  .cy-game-f div{grid-template-columns:80px minmax(0,1fr)}
  .cy-badges{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
  .cy-modrow{gap:10px}
}
@media (max-width:420px){
  .cy-h1{font-size:2.45rem}
  .cyd-models button span.n{display:none}
  .cy-plan{padding:20px}
  .cy-rn{font-size:.68rem;padding:0 8px}
}
@media (prefers-reduced-motion:reduce){
  .cy-coin-tilt{transition:none}
  .cy-step.on .cy-route-l,.cy-step.on .cy-stages i{animation:none}
}

toolu_01AX8LtgTxT4dombq9WGeU9L.content:
/* ================= Cyrus: the AI mod studio (native page) =================
   The studio's own language (deep space, neon branches, the Particle Nebula core) on the
   site's navy, with ONE accent (Cyrus violet) and cyan only for "live". No gradient text,
   no glass on everything: the owner's coin, wordmark and badges carry the colour.
   Dark is the site default; the page also has a full light theme (the Cyrus studio has one),
   switched by the hero toggle (data-cy-theme on the page wrapper). */
main{overflow:clip}
.pg-cy{
  --cy-bg:#060913;--cy-deep:#05030b;--cy-card:#0c0b1c;--cy-card2:#12102a;--cy-card3:#191636;
  --cy-ink:#f2eeff;--cy-ink2:#c6c0e4;--cy-ink3:#948fb8;
  --cy-line:rgba(167,139,250,.14);--cy-line2:rgba(167,139,250,.26);--cy-line3:rgba(167,139,250,.42);
  --cy-acc:#a78bfa;--cy-acc2:#8b6cff;--cy-accink:#c4b5fd;--cy-accsoft:rgba(167,139,250,.14);
  --cy-live:#67e8f9;--cy-livesoft:rgba(103,232,249,.12);--cy-dev:#f0b45a;--cy-devsoft:rgba(240,180,90,.12);
  --cy-shadow:0 30px 80px -40px rgba(10,4,40,.9);
  --cy-stage:radial-gradient(120% 90% at 50% 40%,#140c33 0%,#08051a 46%,#04030b 100%);
  background:var(--cy-bg)
}
.pg-cy[data-cy-theme="light"]{
  --bg:#f5f4fb;--bg-2:#efedf8;--surface:#ffffff;--surface-2:#f6f4fd;--ink:#16122e;--ink-2:#4a4566;--muted:#6b6690;
  --line:rgba(70,50,160,.13);--line-2:rgba(70,50,160,.22);
  --cy-bg:#f5f4fb;--cy-deep:#ffffff;--cy-card:#ffffff;--cy-card2:#f6f4fd;--cy-card3:#ece8fb;
  --cy-ink:#16122e;--cy-ink2:#4a4566;--cy-ink3:#6b6690;
  --cy-line:rgba(70,50,160,.12);--cy-line2:rgba(70,50,160,.22);--cy-line3:rgba(90,60,200,.38);
  --cy-acc:#6d4ae0;--cy-acc2:#5b3bd6;--cy-accink:#5b3bd6;--cy-accsoft:rgba(109,74,224,.1);
  --cy-live:#0e7490;--cy-livesoft:rgba(14,116,144,.1);--cy-dev:#9a5b06;--cy-devsoft:rgba(180,110,10,.1);
  --cy-shadow:0 30px 70px -40px rgba(60,40,140,.35);
  --cy-stage:radial-gradient(120% 90% at 50% 40%,#ffffff 0%,#f3f0fd 55%,#e9e4fb 100%);
  color:var(--cy-ink)
}
.pg-cy .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.cy-eyebrow{margin:0 0 14px;font:600 .76rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--cy-accink)}
.cy-mono{font:500 .74rem var(--f-mono);color:var(--cy-ink3)}
.cy-sec{padding-block:clamp(72px,9vw,128px)}
.cy-tone{background:linear-gradient(180deg,transparent,rgba(18,14,44,.55) 14%,rgba(18,14,44,.55) 86%,transparent)}
.pg-cy[data-cy-theme="light"] .cy-tone{background:linear-gradient(180deg,transparent,rgba(109,74,224,.05) 14%,rgba(109,74,224,.05) 86%,transparent)}
.cy-head{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:20px 40px;margin-bottom:clamp(28px,4vw,48px)}
.cy-head>div{max-width:720px;min-width:0}
.cy-head .h2{max-width:24ch}
.pg-cy .h2,.pg-cy .faq summary{color:var(--cy-ink)}
.pg-cy .lede{color:var(--cy-ink2)}

/* icons filled in by the client mount (data-cy-icon); sized so nothing shifts */
.cy-ic,.cy-mg{display:inline-flex;align-items:center;justify-content:center;flex:none;width:1.15em;height:1.15em;line-height:0}
.cy-ic svg,.cy-mg svg{width:100%;height:100%}
.cy-mg.sm{width:1.05em;height:1.05em}

/* status pills */
.cy-pill{display:inline-flex;align-items:center;gap:6px;height:24px;padding:0 10px;border-radius:999px;font:600 .68rem var(--f-mono);letter-spacing:.08em;text-transform:uppercase;white-space:nowrap}
.cy-pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.cy-pill.live{color:var(--cy-live);background:var(--cy-livesoft)}
.cy-pill.dev{color:var(--cy-dev);background:var(--cy-devsoft)}

/* ---------- motion: reveal once ---------- */
@keyframes cy-up{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes cy-draw{from{stroke-dashoffset:var(--len,600)}to{stroke-dashoffset:0}}
@keyframes cy-pop{from{opacity:0;transform:translate(-50%,-50%) scale(.7)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
@keyframes cy-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
@keyframes cy-sheen{0%{background-position:160% 0}55%,100%{background-position:-60% 0}}
@keyframes cy-tick{from{transform:scale(.4);opacity:0}to{transform:none;opacity:1}}
@keyframes cy-blink{0%,100%{opacity:1}50%{opacity:.35}}
.cy-anim .cy-rv:not(.in){opacity:0}
.cy-anim .cy-rv.in{animation:cy-up .7s cubic-bezier(.2,.7,.2,1) calc(var(--d,0) * 60ms) backwards}

/* ---------- hero ---------- */
.cy-hero{position:relative;isolation:isolate;padding:calc(var(--nav-h) + clamp(40px,6vw,84px)) 0 clamp(40px,6vw,80px)}
.cy-hero-sky{position:absolute;inset:0;z-index:-1;overflow:hidden;pointer-events:none;
  background:
   radial-gradient(38% 46% at 74% 44%,rgba(139,92,246,.22),transparent 70%),
   radial-gradient(30% 38% at 64% 64%,rgba(34,211,238,.10),transparent 70%),
   radial-gradient(1px 1px at 12% 22%,rgba(255,255,255,.55),transparent 60%),
   radial-gradient(1px 1px at 34% 70%,rgba(255,255,255,.35),transparent 60%),
   radial-gradient(1.2px 1.2px at 58% 18%,rgba(255,255,255,.45),transparent 60%),
   radial-gradient(1px 1px at 88% 30%,rgba(255,255,255,.4),transparent 60%),
   radial-gradient(1px 1px at 92% 78%,rgba(255,255,255,.3),transparent 60%),
   radial-gradient(1px 1px at 22% 88%,rgba(255,255,255,.3),transparent 60%)}
.cy-hero-sky::after{content:"";position:absolute;inset:auto 0 0;height:180px;background:linear-gradient(180deg,transparent,var(--cy-bg))}
.pg-cy[data-cy-theme="light"] .cy-hero-sky{background:radial-gradient(40% 48% at 74% 44%,rgba(139,92,246,.16),transparent 70%),radial-gradient(30% 38% at 62% 66%,rgba(34,211,238,.12),transparent 70%)}
.cy-hero-in{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,1fr);align-items:center;gap:clamp(24px,4vw,64px)}
.cy-kicker{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin:0 0 26px;font:600 .74rem var(--f-mono);letter-spacing:.16em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-kicker span{padding-left:14px;border-left:1px solid var(--cy-line2)}
.cy-wm{display:block;height:28px;width:auto}
.cy-wm-l,.cy-coin-l,.cy-badge-l{display:none}
.pg-cy[data-cy-theme="light"] .cy-wm-d,.pg-cy[data-cy-theme="light"] .cy-coin-d,.pg-cy[data-cy-theme="light"] .cy-badge-d{display:none}
.pg-cy[data-cy-theme="light"] .cy-wm-l,.pg-cy[data-cy-theme="light"] .cy-coin-l,.pg-cy[data-cy-theme="light"] .cy-badge-l{display:block}
.cy-h1{margin:0 0 22px;font-size:clamp(2.6rem,5.6vw,4.9rem);line-height:1;letter-spacing:-.045em;font-weight:760;color:var(--cy-ink);text-wrap:balance}
.cy-h1 span{color:var(--cy-accink)}
.cy-lede{margin:0 0 30px;max-width:56ch;color:var(--cy-ink2);font-size:clamp(1.02rem,1.25vw,1.14rem);line-height:1.65}
.cy-ctas{display:flex;flex-wrap:wrap;gap:12px}
.cy-hero-note{margin:22px 0 0;font-size:.86rem;color:var(--cy-ink3)}

.cy-hero-art{position:relative;width:100%;max-width:600px;aspect-ratio:1;margin-inline:auto}
.cy-threads{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.cy-threads path{fill:none;stroke-linecap:round}
.cy-threads .t-glow{stroke-width:6;opacity:.14}
.cy-threads .t-line{stroke-width:1.4;opacity:.75}
.cy-threads .t-soon{stroke-dasharray:2 7;opacity:.45}
.cy-threads .t-dot{opacity:0}
.cy-hero-art.drawn .cy-threads .t-line:not(.t-soon),.cy-hero-art.drawn .cy-threads .t-glow{stroke-dasharray:var(--len) var(--len);animation:cy-draw 1.4s cubic-bezier(.4,.1,.2,1) calc(.25s + var(--i,0) * .09s) backwards}
.cy-coin{position:absolute;left:50%;top:50%;width:54%;aspect-ratio:1;transform:translate(-50%,-50%);perspective:900px;z-index:1}
.cy-coin::before{content:"";position:absolute;left:8%;right:8%;bottom:-10%;height:22%;border-radius:50%;background:radial-gradient(50% 50% at 50% 50%,rgba(139,92,246,.45),transparent 70%);filter:blur(10px);z-index:-1}
.pg-cy[data-cy-theme="light"] .cy-coin::before{background:radial-gradient(50% 50% at 50% 50%,rgba(90,70,190,.22),transparent 70%)}
.cy-coin-tilt{position:relative;width:100%;height:100%;transform:rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transform-style:preserve-3d;transition:transform .6s cubic-bezier(.2,.7,.2,1)}
.cy-coin-img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 26px 40px rgba(40,10,120,.45))}
.pg-cy[data-cy-theme="light"] .cy-coin-img{filter:drop-shadow(0 22px 34px rgba(60,40,140,.22))}
.cy-coin-sheen{position:absolute;inset:0;pointer-events:none;background:linear-gradient(105deg,transparent 38%,rgba(255,255,255,.55) 49%,rgba(255,255,255,.08) 54%,transparent 62%) no-repeat;background-size:220% 100%;background-position:160% 0;mix-blend-mode:soft-light;
  -webkit-mask:url(/cyrus/marketing/coin-dark-sm.webp) center/contain no-repeat;mask:url(/cyrus/marketing/coin-dark-sm.webp) center/contain no-repeat}
.pg-cy[data-cy-theme="light"] .cy-coin-sheen{-webkit-mask-image:url(/cyrus/marketing/coin-light.webp);mask-image:url(/cyrus/marketing/coin-light.webp);mix-blend-mode:overlay}
.cy-hgames{position:absolute;inset:0;margin:0;padding:0;list-style:none;z-index:2}
.cy-hg{position:absolute;display:flex;flex-direction:column;align-items:center;gap:5px;transform:translate(-50%,-50%);font-size:.74rem;color:var(--cy-ink2);white-space:nowrap}
.cy-hg:nth-child(1){left:30%;top:14%}.cy-hg:nth-child(2){left:70%;top:14%}.cy-hg:nth-child(3){left:91%;top:50%}
.cy-hg:nth-child(4){left:72%;top:85%}.cy-hg:nth-child(5){left:28%;top:85%}.cy-hg:nth-child(6){left:9%;top:50%}
.cy-hg .cy-logo{width:46px;height:46px}
.cy-hg-n{font-weight:650;color:var(--cy-ink)}
.cy-hg-s{font:600 .58rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-hg.is-live .cy-hg-s{color:var(--cy-live)}
.cy-hero-art.drawn .cy-hg{animation:cy-pop .6s cubic-bezier(.2,.8,.2,1.2) calc(.9s + var(--i,0) * .09s) backwards}
.cy-logo{position:relative;display:inline-flex;align-items:center;justify-content:center;flex:none;border-radius:50%;overflow:hidden;background:#0b0a18;box-shadow:0 0 0 1.5px rgb(var(--g,167 139 250) / .7),0 0 18px -2px rgb(var(--g,167 139 250) / .55)}
.cy-logo img{width:100%;height:100%;object-fit:cover;border-radius:50%}
.pg-cy[data-cy-theme="light"] .cy-logo{background:#fff;box-shadow:0 0 0 1.5px rgb(var(--g,109 74 224) / .75),0 6px 16px -8px rgb(var(--g,109 74 224) / .6)}
.pg-cy[data-cy-theme="light"] .cy-logo.is-light img{filter:brightness(.25)}
.cy-theme{position:absolute;top:calc(var(--nav-h) + 18px);right:clamp(20px,4vw,40px);display:inline-flex;align-items:center;gap:8px;height:34px;padding:0 14px 0 10px;border-radius:999px;border:1px solid var(--cy-line2);background:color-mix(in srgb,var(--cy-card) 80%,transparent);color:var(--cy-ink2);font:600 .76rem var(--f-body);cursor:pointer;z-index:3}
.cy-theme:hover{color:var(--cy-ink);border-color:var(--cy-line3)}
.cy-theme:focus-visible{outline:2px solid var(--cy-acc);outline-offset:2px}
.cy-theme-i{width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 70% 30%,transparent 42%,currentColor 44%)}
.pg-cy[data-cy-theme="light"] .cy-theme-i{background:radial-gradient(circle,currentColor 38%,transparent 40%),conic-gradient(from 0deg,currentColor 0 4%,transparent 4% 12.5%,currentColor 12.5% 16.5%,transparent 16.5% 25%,currentColor 25% 29%,transparent 29% 37.5%,currentColor 37.5% 41.5%,transparent 41.5% 50%,currentColor 50% 54%,transparent 54% 62.5%,currentColor 62.5% 66.5%,transparent 66.5% 75%,currentColor 75% 79%,transparent 79% 87.5%,currentColor 87.5% 91.5%,transparent 91.5%);-webkit-mask:radial-gradient(circle,#000 70%,transparent 71%);mask:radial-gradient(circle,#000 70%,transparent 71%)}
@media (prefers-reduced-motion:no-preference){
  .cy-coin-sheen{animation:cy-sheen 9s ease-in-out 1.6s infinite}
  .cy-final-coin{animation:cy-float 6s ease-in-out infinite}
}

/* ---------- live demo (React island: components/cyrus/marketing/CyrusDemo.tsx) ---------- */
.cy-demo-flag{display:flex;gap:10px;align-items:baseline;max-width:340px;margin:0;font-size:.84rem;line-height:1.5;color:var(--cy-ink3)}
.cy-demo-flag b{flex:none;padding:3px 9px;border-radius:999px;background:var(--cy-accsoft);color:var(--cy-accink);font:700 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase}
.cy-demo{position:relative;border-radius:28px;border:1px solid var(--cy-line2);background:var(--cy-stage);box-shadow:var(--cy-shadow);overflow:hidden;min-height:clamp(560px,62vw,760px)}
.cy-demo-fallback{display:grid;place-items:center;min-height:inherit;padding:32px;text-align:center;color:var(--cy-ink3)}
.cy-demo.on .cy-demo-fallback{display:none}
.cyd{position:relative;display:grid;grid-template-rows:minmax(0,1fr) auto;min-height:inherit}
.cyd-stage{position:relative;min-height:clamp(380px,44vw,560px);overflow:hidden;touch-action:pan-y;cursor:default}
.cyd-canvas,.cyd-core{position:absolute;left:0;top:0;pointer-events:none}
.cyd-core{will-change:transform}
.cyd-nodes{position:absolute;inset:0}
.cyd-node{position:absolute;left:0;top:0;will-change:transform;transition:opacity .45s ease}
.cyd-node.off{opacity:.22}
.cyd-game{display:flex;flex-direction:column;align-items:center;gap:6px;transform:translate(-50%,-50%)}
.cyd-game button{all:unset;cursor:pointer;border-radius:50%}
.cyd-game button:focus-visible{outline:2px solid var(--cy-acc);outline-offset:4px}
.cyd-game .cy-logo{width:var(--sz,64px);height:var(--sz,64px);transition:box-shadow .3s ease,transform .3s ease}
.cyd-game.hit .cy-logo{transform:scale(1.08);box-shadow:0 0 0 2px rgb(var(--g)),0 0 32px 2px rgb(var(--g) / .8)}
.cyd-gname{padding:2px 9px;border-radius:999px;background:rgba(6,4,18,.72);border:1px solid rgb(var(--g) / .35);font:650 .72rem var(--f-body);color:#f2eeff;white-space:nowrap}
.cyd-gname em{margin-left:6px;font:600 .56rem var(--f-mono);font-style:normal;letter-spacing:.1em;text-transform:uppercase;color:rgba(242,238,255,.55)}
.cyd-gname em.live{color:#67e8f9}
.cyd-cat{display:flex;align-items:center;gap:8px;transform:translate(-50%,-50%)}
.cyd-cat[data-side="left"]{flex-direction:row-reverse}
.cyd-corb{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:rgba(8,6,22,.85);color:rgb(var(--g));box-shadow:0 0 0 1px rgb(var(--g) / .55),0 0 14px -2px rgb(var(--g) / .5);font-size:17px;transition:box-shadow .3s,transform .3s}
.cyd-cat.hit .cyd-corb{transform:scale(1.12);box-shadow:0 0 0 1.5px rgb(var(--g)),0 0 24px 2px rgb(var(--g) / .75)}
.cyd-clabel{font:600 .7rem var(--f-body);color:rgba(242,238,255,.82);white-space:nowrap}
.cyd-pill{display:flex;align-items:center;gap:7px;height:28px;padding:0 12px 0 9px;border-radius:999px;background:rgba(8,6,22,.9);border:1px solid rgb(var(--g) / .6);box-shadow:0 0 20px -4px rgb(var(--g) / .7);font:650 .74rem var(--f-body);color:#fff;white-space:nowrap;transform:translate(0,-50%)}
.cyd-pill[data-side="left"]{transform:translate(-100%,-50%)}
.cyd-pill i{width:8px;height:8px;border-radius:2px;background:rgb(var(--g));box-shadow:0 0 8px rgb(var(--g))}
.cyd-pill.forging i{animation:cy-blink .8s ease-in-out infinite}
.cyd-pill small{font:600 .58rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:rgba(242,238,255,.55)}
.cyd-corelabel{transform:translate(-50%,0);display:flex;align-items:center;gap:6px;font:600 .62rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:rgba(242,238,255,.6);white-space:nowrap}
.cyd-corelabel i{width:6px;height:6px;border-radius:50%;background:#67e8f9;box-shadow:0 0 8px #67e8f9}
.pg-cy[data-cy-theme="light"] .cyd-gname{background:rgba(255,255,255,.9);color:#16122e}
.pg-cy[data-cy-theme="light"] .cyd-gname em{color:#6b6690}.pg-cy[data-cy-theme="light"] .cyd-gname em.live{color:#0e7490}
.pg-cy[data-cy-theme="light"] .cyd-corb{background:#fff}
.pg-cy[data-cy-theme="light"] .cyd-clabel{color:#2c2650}
.pg-cy[data-cy-theme="light"] .cyd-pill{background:#fff;color:#16122e}
.pg-cy[data-cy-theme="light"] .cyd-pill small{color:#6b6690}
.pg-cy[data-cy-theme="light"] .cyd-corelabel{color:#6b6690}

/* the result card */
.cyd-card{position:absolute;right:18px;top:18px;width:min(340px,calc(100% - 36px));max-height:calc(100% - 36px);overflow:auto;padding:18px;border-radius:20px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow);color:var(--cy-ink);transition:opacity .35s ease,transform .35s ease;z-index:3}
.cyd-card[hidden]{display:block;opacity:0;transform:translateY(8px);pointer-events:none}
.cyd-card-k{display:flex;align-items:center;gap:8px;margin:0 0 4px;font:600 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cyd-card h3{margin:0 0 4px;font-size:1.12rem;letter-spacing:-.01em}
.cyd-card p{margin:0 0 12px;font-size:.84rem;line-height:1.5;color:var(--cy-ink2)}
.cyd-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 14px}
.cyd-facts div{padding:8px 10px;border-radius:12px;background:var(--cy-card2);border:1px solid var(--cy-line)}
.cyd-facts dt{font:600 .58rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cyd-facts dd{margin:3px 0 0;display:flex;align-items:center;gap:6px;font-size:.84rem;font-weight:650}
.cyd-steps{display:grid;gap:6px;margin:0 0 12px;padding:0;list-style:none}
.cyd-steps li{display:grid;grid-template-columns:18px 1fr auto;align-items:center;gap:8px;font-size:.8rem;color:var(--cy-ink3)}
.cyd-steps li i{width:14px;height:14px;border-radius:50%;border:1.5px solid var(--cy-line3)}
.cyd-steps li.on{color:var(--cy-ink)}
.cyd-steps li.on i{border-color:var(--cy-acc);box-shadow:inset 0 0 0 3px var(--cy-card),inset 0 0 0 8px var(--cy-acc);animation:cy-blink 1s ease-in-out infinite}
.cyd-steps li.done{color:var(--cy-ink2)}
.cyd-steps li.done i{border-color:var(--cy-live);background:var(--cy-live);box-shadow:inset 0 0 0 3px var(--cy-card)}
.cyd-steps li.skip{opacity:.55}
.cyd-steps small{font:500 .64rem var(--f-mono);color:var(--cy-ink3)}
.cyd-code{margin:0 0 10px;padding:10px 12px;border-radius:12px;background:var(--cy-deep);border:1px solid var(--cy-line);font:500 .7rem/1.6 var(--f-mono);color:var(--cy-ink2);white-space:pre;overflow:auto}
.cyd-note{display:block;font-size:.74rem;line-height:1.45;color:var(--cy-ink3)}
.cyd-note.soon{color:var(--cy-dev)}
.cyd-x{position:absolute;right:10px;top:10px;width:28px;height:28px;border-radius:50%;border:0;background:var(--cy-card2);color:var(--cy-ink2);cursor:pointer;font-size:14px;line-height:28px}
.cyd-x:focus-visible{outline:2px solid var(--cy-acc)}

/* the prompt dock (mirrors the studio's) */
.cyd-dockwrap{position:relative;z-index:4;padding:0 clamp(12px,2vw,22px) clamp(14px,2vw,22px)}
.cyd-dock{max-width:860px;margin:0 auto;padding:12px 12px 10px;border-radius:20px;background:color-mix(in srgb,var(--cy-card) 94%,transparent);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow)}
.cyd-route{display:flex;align-items:center;gap:8px;min-height:24px;margin:0 0 8px;padding:0 4px;font:600 .7rem var(--f-mono);letter-spacing:.04em;color:var(--cy-ink3)}
.cyd-route b{color:var(--cy-accink);font-weight:650}
.cyd-route i{width:6px;height:6px;border-radius:50%;background:var(--cy-acc);box-shadow:0 0 8px var(--cy-acc)}
.cyd-in{display:block;width:100%;min-height:52px;max-height:120px;padding:8px 6px;border:0;outline:0;resize:none;background:transparent;color:var(--cy-ink);font:500 1rem/1.5 var(--f-body)}
.cyd-in::placeholder{color:var(--cy-ink3)}
.cyd-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding-top:8px;border-top:1px solid var(--cy-line)}
.cyd-models{display:inline-flex;padding:3px;border-radius:12px;background:var(--cy-card2);border:1px solid var(--cy-line)}
.cyd-models button{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 10px;border:0;border-radius:9px;background:none;color:var(--cy-ink3);font:600 .78rem var(--f-body);cursor:pointer}
.cyd-models button[aria-pressed="true"]{background:var(--cy-card3);color:var(--cy-ink);box-shadow:0 0 0 1px rgb(var(--m) / .55)}
.cyd-models button .cy-mg{color:rgb(var(--m))}
.cyd-models button:focus-visible{outline:2px solid var(--cy-acc);outline-offset:1px}
.cyd-est{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3);white-space:nowrap}
.cyd-est b{color:var(--cy-ink2);font-weight:600}
.cyd-go{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 16px;border:0;border-radius:11px;background:var(--cy-acc2);color:#fff;font:700 .84rem var(--f-body);cursor:pointer}
.cyd-go:disabled{opacity:.5;cursor:default}
.cyd-go:focus-visible{outline:2px solid var(--cy-ink);outline-offset:2px}
.cyd-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;max-width:860px;margin:12px auto 0}
.cyd-chips span{font:600 .64rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3);align-self:center}
.cyd-chips button{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 12px 0 6px;border-radius:999px;border:1px solid var(--cy-line2);background:var(--cy-card);color:var(--cy-ink2);font:600 .78rem var(--f-body);cursor:pointer}
.cyd-chips button:hover{color:var(--cy-ink);border-color:var(--cy-line3)}
.cyd-chips button:focus-visible{outline:2px solid var(--cy-acc)}
.cyd-chips .cy-logo{width:22px;height:22px;box-shadow:0 0 0 1px rgb(var(--g) / .7)}
.cyd-clarify{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
.cyd-clarify button{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px 0 4px;border-radius:999px;border:1px solid var(--cy-line2);background:var(--cy-card2);color:var(--cy-ink);font:600 .74rem var(--f-body);cursor:pointer}
.cyd-clarify .cy-logo{width:20px;height:20px}

/* ---------- the flow ---------- */
.cy-flow{position:relative;margin:0;padding:0;list-style:none;counter-reset:s}
.cy-flow::before{content:"";position:absolute;left:21px;top:30px;bottom:30px;width:1px;background:linear-gradient(180deg,var(--cy-line2),var(--cy-line) 85%,transparent)}
.cy-step{position:relative;display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:clamp(24px,4vw,64px);min-height:min(74vh,640px);align-items:start;padding:clamp(18px,3vw,28px) 0}
.cy-step-t{position:relative;padding-left:64px;padding-top:clamp(12px,6vh,64px)}
.cy-step-n{position:absolute;left:0;top:clamp(8px,6vh,60px);display:grid;place-items:center;width:43px;height:43px;border-radius:50%;background:var(--cy-bg);border:1px solid var(--cy-line2);font:600 .78rem var(--f-mono);color:var(--cy-ink3);transition:all .4s ease}
.cy-step.on .cy-step-n{border-color:var(--cy-acc);color:var(--cy-ink);box-shadow:0 0 0 4px var(--cy-accsoft),0 0 22px -4px var(--cy-acc)}
.cy-step h3{display:inline;margin:0 12px 0 0;font-size:clamp(1.35rem,2.2vw,1.8rem);letter-spacing:-.02em;color:var(--cy-ink)}
.cy-step-t .cy-pill{vertical-align:4px}
.cy-step-t p{margin:14px 0 0;max-width:46ch;color:var(--cy-ink2);line-height:1.65}
.cy-step-v{position:sticky;top:calc(var(--nav-h) + 48px)}
.cy-v{position:relative;padding:clamp(18px,2.4vw,26px);border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow);transition:transform .6s cubic-bezier(.2,.7,.2,1),opacity .6s ease}
.cy-anim .cy-step:not(.seen) .cy-v{opacity:.35;transform:translateY(14px) scale(.985)}
.cy-v-cap{margin:14px 0 0;font:600 .6rem var(--f-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--cy-ink3)}
/* 1 dock */
.cy-dock-in{min-height:84px;padding:4px 2px 14px;font-size:1.02rem;line-height:1.55;color:var(--cy-ink)}
.cy-dock-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:12px;border-top:1px solid var(--cy-line)}
.cy-chip{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px;border-radius:9px;background:var(--cy-card2);border:1px solid var(--cy-line2);font:600 .78rem var(--f-body);color:var(--cy-ink)}
.cy-chip .cy-mg{color:#818cf8}
.cy-dock-est{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-dock-go{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:var(--cy-acc2);color:#fff;font-weight:800}
/* 2 route */
.cy-v-route{min-height:220px}
.cy-v-route svg{position:absolute;inset:26px 26px auto;width:calc(100% - 52px);height:150px}
.cy-route-l{fill:none;stroke:var(--cy-acc);stroke-width:2;stroke-dasharray:4 7;opacity:.75}
.cy-step.on .cy-route-l{animation:cy-dash 1.2s linear infinite}
@keyframes cy-dash{to{stroke-dashoffset:-22}}
.cy-rn{position:absolute;display:inline-flex;align-items:center;height:28px;padding:0 11px;border-radius:999px;background:var(--cy-card2);border:1px solid var(--cy-line2);font:650 .76rem var(--f-body);color:var(--cy-ink);transform:translate(-50%,-50%);white-space:nowrap}
.cy-rn.core{left:calc(26px + (100% - 52px) * .11);top:calc(26px + 75px);border-color:var(--cy-acc)}
.cy-rn.game{left:calc(26px + (100% - 52px) * .39);top:calc(26px + 40px);border-color:rgb(52 211 153 / .7)}
.cy-rn.cat{left:calc(26px + (100% - 52px) * .66);top:calc(26px + 75px);border-color:rgb(251 113 133 / .7)}
.cy-rn.mod{left:calc(26px + (100% - 52px) * .86);top:calc(26px + 110px);border-color:rgb(251 113 133 / .9);box-shadow:0 0 18px -6px rgb(251 113 133)}
.cy-route-chip{position:absolute;left:26px;right:26px;bottom:22px;margin:0;display:flex;align-items:center;gap:8px;font:600 .74rem var(--f-mono);color:var(--cy-accink)}
.cy-route-chip::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--cy-acc);box-shadow:0 0 8px var(--cy-acc)}
/* 3 stages */
.cy-stages{display:grid;gap:4px;margin:0;padding:0;list-style:none}
.cy-stages li{display:grid;grid-template-columns:22px auto 1fr;align-items:center;gap:12px;padding:10px 4px;border-bottom:1px solid var(--cy-line)}
.cy-stages li:last-child{border-bottom:0}
.cy-stages i{width:16px;height:16px;border-radius:50%;border:1.5px solid var(--cy-line3)}
.cy-stages b{font-size:.94rem;color:var(--cy-ink)}
.cy-stages small{justify-self:end;font:500 .72rem var(--f-mono);color:var(--cy-ink3);text-align:right}
.cy-step.on .cy-stages i{animation:cy-tick .4s cubic-bezier(.2,.8,.2,1.3) calc(.25s + var(--d) * .32s) both;border-color:var(--cy-live);background:radial-gradient(circle,var(--cy-live) 38%,transparent 42%)}
/* 4 code */
.cy-tabs{display:flex;flex-wrap:wrap;gap:4px;margin:0 0 12px}
.cy-tabs span{padding:5px 10px;border-radius:8px;font:600 .74rem var(--f-body);color:var(--cy-ink3)}
.cy-tabs span.on{background:var(--cy-accsoft);color:var(--cy-ink)}
.cy-code{margin:0;padding:14px 16px;border-radius:14px;background:var(--cy-deep);border:1px solid var(--cy-line);font:500 .78rem/1.65 var(--f-mono);color:var(--cy-ink2);overflow:auto}
.cy-code b{color:var(--cy-accink);font-weight:600}
.cy-vers{display:grid;gap:6px;margin:12px 0 0;padding:0;list-style:none;font-size:.84rem;color:var(--cy-ink2)}
.cy-vers li{display:flex;gap:10px;align-items:baseline}
.cy-vers b{font:600 .72rem var(--f-mono);color:var(--cy-live)}
/* 5 page */
.cy-page-h{display:flex;align-items:center;gap:12px;margin:0 0 10px}
.cy-page-h b{display:block;font-size:1.06rem;color:var(--cy-ink)}
.cy-page-h small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-page-ic{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:rgba(251,113,133,.12);color:#fb7185;font-size:22px;box-shadow:0 0 0 1px rgba(251,113,133,.4)}
.cy-v-page>p{margin:0 0 14px;color:var(--cy-ink2);font-size:.92rem}
.cy-page-f{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}
.cy-page-f img{height:44px;width:auto}
.cy-btnlike{display:inline-flex;align-items:center;height:34px;padding:0 14px;border-radius:10px;border:1px solid var(--cy-line3);font:650 .8rem var(--f-body);color:var(--cy-ink)}
/* 6 tree */
.cy-v-tree{padding-bottom:20px}
.cy-tree-o,.cy-v-tree li{display:flex;flex-direction:column;padding:12px 14px;border-radius:14px;background:var(--cy-card2);border:1px solid var(--cy-line2)}
.cy-tree-o{border-color:var(--cy-acc)}
.cy-tree-o b,.cy-v-tree li b{font-size:.92rem;color:var(--cy-ink)}
.cy-tree-o small,.cy-v-tree li small{font:500 .7rem var(--f-mono);color:var(--cy-ink3)}
.cy-v-tree ul{position:relative;display:grid;gap:10px;margin:14px 0 0 26px;padding:0 0 0 18px;list-style:none;border-left:1px dashed var(--cy-line3)}
.cy-v-tree li{position:relative}
.cy-v-tree li::before{content:"";position:absolute;left:-19px;top:50%;width:18px;border-top:1px dashed var(--cy-line3)}
/* 7 install */
.cy-srv{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:14px;background:var(--cy-card2);border:1px solid var(--cy-line2);margin:0 0 14px}
.cy-srv b{color:var(--cy-ink)}.cy-srv small{margin-left:auto;font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-srv-dot{width:8px;height:8px;border-radius:50%;background:#34e3a2;box-shadow:0 0 8px #34e3a2}
.cy-checks{display:grid;gap:10px;margin:0;padding:0;list-style:none}
.cy-checks li{display:flex;align-items:center;gap:10px;font-size:.92rem;color:var(--cy-ink2)}
.cy-checks li::before{content:"";flex:none;width:18px;height:18px;border-radius:50%;background:var(--cy-livesoft);box-shadow:inset 0 0 0 1.5px var(--cy-live);-webkit-mask:none}
.cy-step.on .cy-checks li::before{background:radial-gradient(circle,var(--cy-live) 34%,var(--cy-livesoft) 38%)}
/* 8 + install panel: mod rows */
.cy-modrow{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px 4px;border-bottom:1px solid var(--cy-line)}
.cy-modrow:last-of-type{border-bottom:0}
.cy-modrow b{display:block;font-size:.92rem;color:var(--cy-ink)}
.cy-modrow small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}
.cy-tog{position:relative;width:34px;height:20px;border-radius:999px;background:var(--cy-card3);box-shadow:inset 0 0 0 1px var(--cy-line2)}
.cy-tog::after{content:"";position:absolute;left:3px;top:3px;width:14px;height:14px;border-radius:50%;background:var(--cy-ink3);transition:transform .3s}
.cy-tog.on{background:color-mix(in srgb,var(--cy-acc) 55%,transparent)}
.cy-tog.on::after{transform:translateX(14px);background:#fff}
.cy-upd{padding:4px 10px;border-radius:8px;background:var(--cy-accsoft);font:600 .72rem var(--f-body);color:var(--cy-accink);white-space:nowrap}
.cy-modrow.warn small{color:var(--cy-dev)}
.cy-warn-i{display:grid;place-items:center;width:20px;height:20px;border-radius:6px;background:var(--cy-devsoft);color:var(--cy-dev);font:800 .8rem var(--f-mono)}

/* ---------- games ---------- */
.cy-games{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:0;padding:0;list-style:none}
.cy-game{position:relative;display:flex;flex-direction:column;gap:12px;padding:22px 22px 20px 26px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);overflow:hidden}
.cy-game::before{content:"";position:absolute;left:0;top:18px;bottom:18px;width:3px;border-radius:0 3px 3px 0;background:rgb(var(--g));box-shadow:0 0 16px rgb(var(--g) / .7)}
.cy-game.is-live{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:40px;padding:28px 30px 26px 34px;border-color:rgb(var(--g) / .45);background:linear-gradient(110deg,rgb(var(--g) / .08),transparent 46%),var(--cy-card)}
.cy-game.is-live>*{grid-column:1}
.cy-game.is-live .cy-game-f,.cy-game.is-live .cy-game-why,.cy-game.is-live .cy-game-cats{grid-column:2}
.cy-game.is-live .cy-game-f{grid-row:1/span 2}
.cy-game-head{display:flex;align-items:center;gap:14px}
.cy-game-head .cy-logo{width:52px;height:52px}
.cy-game.is-live .cy-game-head .cy-logo{width:64px;height:64px}
.cy-game-t{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px}
.cy-game-t b{font-size:1.16rem;letter-spacing:-.01em;color:var(--cy-ink)}
.cy-game.is-live .cy-game-t b{font-size:1.5rem}
.cy-status{display:inline-flex;align-items:center;gap:6px;font:600 .64rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-status::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.cy-status.live{color:var(--cy-live)}
.cy-game-b{margin:0;color:var(--cy-ink2);font-size:.94rem}
.cy-game-f{display:grid;gap:8px;margin:0}
.cy-game-f div{display:grid;grid-template-columns:90px minmax(0,1fr);gap:12px;align-items:baseline}
.cy-game-f dt{font:600 .62rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-game-f dd{margin:0;font-size:.9rem;color:var(--cy-ink)}
.cy-game-why{margin:0;font-size:.86rem;line-height:1.55;color:var(--cy-ink3)}
.cy-game-cats{display:flex;flex-wrap:wrap;gap:6px;margin:0;padding:0;list-style:none}
.cy-game-cats li{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 10px 0 8px;border-radius:9px;background:var(--cy-card2);border:1px solid var(--cy-line);font:600 .76rem var(--f-body);color:var(--cy-ink2)}
.cy-game-cats li .cy-ic{color:rgb(var(--c));font-size:15px}
.cy-game-go{margin-top:auto;align-self:flex-start;font:650 .84rem var(--f-body);color:var(--cy-accink);text-decoration:none}
.cy-game-go:hover{text-decoration:underline}
.cy-game.is-live .cy-game-go{grid-column:1}

/* ---------- models + plans ---------- */
.cy-models{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0 0 20px;padding:0;list-style:none}
.cy-model{position:relative;display:flex;flex-direction:column;gap:6px;padding:22px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2)}
.cy-model-g{display:grid;place-items:center;width:56px;height:56px;margin:0 0 8px;border-radius:18px;background:rgb(var(--m) / .12);color:rgb(var(--m));box-shadow:0 0 0 1px rgb(var(--m) / .4),0 0 30px -10px rgb(var(--m));font-size:30px}
.cy-model-n{font-size:1.3rem;letter-spacing:-.015em;color:var(--cy-ink)}
.cy-model-tag{font:600 .66rem var(--f-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--cy-ink3)}
.cy-model p{margin:6px 0 4px;color:var(--cy-ink2);font-size:.92rem}
.cy-meter{display:flex;gap:4px;margin:2px 0 10px}
.cy-meter i{width:22px;height:5px;border-radius:3px;background:var(--cy-line2)}
.cy-meter i.on{background:rgb(var(--m))}
.cy-model-f{display:grid;gap:6px;margin:0 0 12px;padding:12px 0 0;border-top:1px solid var(--cy-line)}
.cy-model-f div{display:flex;justify-content:space-between;gap:12px}
.cy-model-f dt{font-size:.84rem;color:var(--cy-ink3)}
.cy-model-f dd{margin:0;font:600 .8rem var(--f-mono);color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-model-u{margin-top:auto;font-size:.8rem;color:var(--cy-accink)}
.cy-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:0;padding:0;list-style:none}
.cy-plan{display:flex;flex-direction:column;padding:24px;border-radius:24px;background:var(--cy-card);border:1px solid var(--cy-line2)}
.cy-plan.is-mid{border-color:var(--cy-acc);box-shadow:0 0 0 1px var(--cy-acc) inset,0 30px 80px -40px rgba(139,92,246,.6)}
.cy-plan-h{display:flex;align-items:center;justify-content:space-between;gap:10px}
.cy-plan-h b{font-size:1.14rem;color:var(--cy-ink)}
.cy-plan-k{padding:3px 9px;border-radius:999px;background:var(--cy-accsoft);font:600 .62rem var(--f-mono);letter-spacing:.1em;text-transform:uppercase;color:var(--cy-accink)}
.cy-plan-p{margin:14px 0 4px;display:flex;align-items:baseline;gap:4px}
.cy-plan-p span{font-size:2.3rem;font-weight:800;letter-spacing:-.035em;color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-plan-p small{color:var(--cy-ink3)}
.cy-plan-t{display:flex;align-items:center;gap:8px;margin:0 0 4px;color:var(--cy-ink2)}
.cy-plan-t b{color:var(--cy-ink)}
.cy-coin{}
.cy-plan-t .cy-coin,.cy-plan-t i[data-cy-icon="coin"]{width:20px;height:20px;position:static;transform:none;perspective:none;border-radius:50%;background:url(/cyrus/marketing/token-coin.webp) center/cover}
.cy-plan-u{margin:0 0 16px;font-size:.84rem;color:var(--cy-ink3)}
.cy-plan-est{display:grid;gap:10px;margin:0 0 20px;padding:14px 0 0;list-style:none;border-top:1px solid var(--cy-line)}
.cy-plan-est li{display:grid;grid-template-columns:minmax(0,auto) 1fr;gap:2px 12px;font-size:.84rem;color:var(--cy-ink2)}
.cy-plan-est li>span:nth-child(3){grid-column:2}
.cy-pl-m{display:inline-flex;align-items:center;gap:6px;grid-row:span 2;font-weight:650;color:var(--cy-ink)}
.cy-plan-est b{color:var(--cy-ink);font-variant-numeric:tabular-nums}
.cy-plan-go{margin-top:auto;justify-content:center}
.cy-plan-note{display:block;margin-top:12px;font-size:.76rem;color:var(--cy-ink3)}
.cy-plan-foot{display:grid;gap:8px;max-width:820px;margin:26px auto 0;text-align:center;color:var(--cy-ink2);font-size:.94rem}
.cy-plan-foot p{margin:0}.cy-plan-foot p:empty{display:none}
.cy-plan-foot b{color:var(--cy-ink)}
.cy-fine{font-size:.8rem;color:var(--cy-ink3)}

/* ---------- community ---------- */
.cy-com{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.cy-ticks{display:grid;gap:14px;margin:26px 0 0;padding:0;list-style:none}
.cy-ticks li{position:relative;padding-left:28px;color:var(--cy-ink2);line-height:1.6}
.cy-ticks li::before{content:"";position:absolute;left:0;top:.45em;width:14px;height:14px;border-radius:5px;background:var(--cy-accsoft);box-shadow:inset 0 0 0 1.5px var(--cy-acc)}
.cy-ticks b{color:var(--cy-ink)}
.cy-badges{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.cy-badge{margin:0;display:flex;flex-direction:column;align-items:center;gap:12px;padding:22px 18px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);text-align:center}
.cy-badge img{width:auto;max-width:100%;object-fit:contain}
.cy-badge.b-pill{grid-column:1/-1}
.cy-badge.b-pill img{height:clamp(64px,8vw,96px)}
.cy-badge.b-laurel img{height:clamp(110px,12vw,150px)}
.cy-badge.b-shield img{height:clamp(110px,12vw,150px)}
.cy-badge figcaption{display:grid;gap:4px;font-size:.84rem;line-height:1.5;color:var(--cy-ink3);max-width:30ch}
.cy-badge figcaption b{font-size:.94rem;color:var(--cy-ink)}

/* ---------- install ---------- */
.cy-inst{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,5vw,72px);align-items:center}
.cy-panel{padding:18px 20px;border-radius:22px;background:var(--cy-card);border:1px solid var(--cy-line2);box-shadow:var(--cy-shadow)}
.cy-panel-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:0 4px 12px;border-bottom:1px solid var(--cy-line)}
.cy-panel-h b{font-size:1.02rem;color:var(--cy-ink)}
.cy-panel-h small{font:500 .72rem var(--f-mono);color:var(--cy-ink3)}

/* ---------- final ---------- */
.cy-final{padding-block:clamp(96px,12vw,168px)}
.cy-final-coin{display:block;width:64px;height:64px;margin:0 auto 18px}
.pg-cy .cy-final h2,.pg-cy .cy-final p{color:var(--cy-ink)}
.pg-cy .cy-final>div>p:not(.nxm-eyebrow){color:var(--cy-ink2)}

/* light theme: shared design classes that hardcode dark colours */
.pg-cy[data-cy-theme="light"] .faq details{border-color:var(--cy-line2)}
.pg-cy[data-cy-theme="light"] .nxm-glassbtn{color:var(--cy-ink);background:#fff;border-color:var(--cy-line3)}

/* ---------- responsive ---------- */
@media (max-width:1080px){
  .cy-models,.cy-plans{grid-template-columns:minmax(0,1fr)}
  .cy-models{grid-template-columns:repeat(3,minmax(0,1fr))}
  .cy-plans{max-width:560px;margin-inline:auto}
}
@media (max-width:900px){
  .cy-hero-in{grid-template-columns:minmax(0,1fr)}
  .cy-hero-art{order:-1;max-width:440px}
  .cy-theme{top:calc(var(--nav-h) + 10px)}
  .cy-step{grid-template-columns:minmax(0,1fr);min-height:0;gap:18px}
  .cy-step-v{position:relative;top:auto;margin-left:64px}
  .cy-step-t,.cy-step-n{padding-top:0;top:0}
  .cy-game.is-live{display:flex}
  .cy-com,.cy-inst{grid-template-columns:minmax(0,1fr)}
  .cy-inst-v{order:2}
  .cyd-card{position:relative;right:auto;top:auto;width:auto;max-height:none;margin:0 12px 12px}
  .cyd-card[hidden]{display:none}
}
@media (max-width:760px){
  .cy-games,.cy-models{grid-template-columns:minmax(0,1fr)}
  .cy-head{margin-bottom:24px}
  .cy-demo{border-radius:22px;margin-inline:-6px}
  .cy-step-v{margin-left:0}
  .cy-flow::before{display:none}
  .cy-step-t{padding-left:56px}
  .cy-step-n{width:40px;height:40px}
  .cy-hg .cy-logo{width:38px;height:38px}
  .cy-hg{font-size:.68rem}
  .cyd-est{margin-left:0;flex-basis:100%;order:-1}
  .cyd-go{margin-left:auto}
  .cyd-models button{padding:0 8px}
  .cy-game{padding:20px 18px 18px 22px}
  .cy-game-f div{grid-template-columns:80px minmax(0,1fr)}
  .cy-badges{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
  .cy-modrow{gap:10px}
}
@media (max-width:420px){
  .cy-h1{font-size:2.45rem}
  .cyd-models button span.n{display:none}
  .cy-plan{padding:20px}
  .cy-rn{font-size:.68rem;padding:0 8px}
}
@media (prefers-reduced-motion:reduce){
  .cy-coin-tilt{transition:none}
  .cy-step.on .cy-route-l,.cy-step.on .cy-stages i{animation:none}
}

