/* ============ Cyrus page: hero coin + threads, theme, reveal, the flow ============
   The live demo itself is a React island (components/cyrus/marketing/CyrusDemo.tsx), mounted
   into [data-cyrus-demo] by app/nxm/cyrus/layout.tsx; the icons ([data-cy-icon]) too. */
(function () {
  var page = document.querySelector('.pg-cy') || document.querySelector('.nxm-p');
  var main = document.getElementById('main');
  if (!page || !main) return;
  var RMQ = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- theme: dark (site default) or the studio's light theme, remembered per browser ---- */
  var tbtn = document.getElementById('cy-theme');
  var setTheme = function (t, save) {
    page.setAttribute('data-cy-theme', t);
    if (tbtn) {
      tbtn.setAttribute('aria-pressed', t === 'light' ? 'true' : 'false');
      var lab = tbtn.querySelector('.cy-theme-t'); if (lab) lab.textContent = t === 'light' ? 'Dark' : 'Light';
      tbtn.setAttribute('aria-label', t === 'light' ? 'Switch the page to dark' : 'Switch the page to light');
    }
    if (save) { try { localStorage.setItem('cy-mkt-theme', t); } catch (e) {} }
    window.dispatchEvent(new CustomEvent('cy-theme', { detail: t }));
  };
  var saved = null; try { saved = localStorage.getItem('cy-mkt-theme'); } catch (e) {}
  setTheme(saved === 'light' ? 'light' : 'dark', false);
  if (tbtn) tbtn.addEventListener('click', function () { setTheme(page.getAttribute('data-cy-theme') === 'light' ? 'dark' : 'light', true); });

  /* ---- reveal once on entry ---- */
  var io = null;
  if (!RMQ && 'IntersectionObserver' in window) {
    main.classList.add('cy-anim');
    io = new IntersectionObserver(function (es) {
      es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.01 });
    document.querySelectorAll('.cy-rv').forEach(function (el) { io.observe(el); });
  } else {
    document.querySelectorAll('.cy-rv').forEach(function (el) { el.classList.add('in'); });
  }

  /* ---- hero: threads from the coin to each game, drawn once; a light runs to the live game ---- */
  var art = document.querySelector('.cy-hero-art');
  var svg = art && art.querySelector('.cy-threads');
  var NS = 'http://www.w3.org/2000/svg';
  var drawThreads = function () {
    if (!art || !svg) return;
    var box = art.getBoundingClientRect();
    if (!box.width) return;
    var s = 600 / box.width;
    var cx = 300, cy = 300, rr = 300 * 0.54 * 0.82; // coin rim, in the 600 box
    while (svg.firstChild) svg.removeChild(svg.firstChild);
    var defs = document.createElementNS(NS, 'defs'); svg.appendChild(defs);
    var live = null;
    art.querySelectorAll('.cy-hg').forEach(function (li, i) {
      var lb = li.querySelector('.cy-logo').getBoundingClientRect();
      var x = (lb.left + lb.width / 2 - box.left) * s, y = (lb.top + lb.height / 2 - box.top) * s;
      var dx = x - cx, dy = y - cy, d = Math.hypot(dx, dy) || 1;
      var ax = cx + dx / d * rr, ay = cy + dy / d * rr;
      var r2 = (lb.width / 2 + 4) * s;
      var bx = x - dx / d * r2, by = y - dy / d * r2;
      // leave the coin radially, arrive along the dominant axis (the studio's branch shape)
      var c1x = ax + dx / d * d * 0.35, c1y = ay + dy / d * d * 0.35;
      var horiz = Math.abs(dx) > Math.abs(dy) * 0.8;
      var c2x = horiz ? bx - (bx - ax) * 0.4 : bx, c2y = horiz ? by : by - (by - ay) * 0.4;
      var dd = 'M' + ax.toFixed(1) + ' ' + ay.toFixed(1) + ' C' + c1x.toFixed(1) + ' ' + c1y.toFixed(1) + ' ' + c2x.toFixed(1) + ' ' + c2y.toFixed(1) + ' ' + bx.toFixed(1) + ' ' + by.toFixed(1);
      var rgb = getComputedStyle(li).getPropertyValue('--g').trim() || '167 139 250';
      var gid = 'cyg' + i;
      var lg = document.createElementNS(NS, 'linearGradient');
      lg.setAttribute('id', gid); lg.setAttribute('gradientUnits', 'userSpaceOnUse');
      lg.setAttribute('x1', ax); lg.setAttribute('y1', ay); lg.setAttribute('x2', bx); lg.setAttribute('y2', by);
      lg.innerHTML = '<stop offset="0" stop-color="rgb(196 181 253)"/><stop offset="1" stop-color="rgb(' + rgb + ')"/>';
      defs.appendChild(lg);
      var soon = !li.classList.contains('is-live');
      ['t-glow', 't-line'].forEach(function (cls) {
        var p = document.createElementNS(NS, 'path');
        p.setAttribute('d', dd); p.setAttribute('class', cls + (soon && cls === 't-line' ? ' t-soon' : ''));
        p.setAttribute('stroke', 'url(#' + gid + ')');
        p.style.setProperty('--i', String(i));
        svg.appendChild(p);
        try { p.style.setProperty('--len', String(Math.ceil(p.getTotalLength()))); } catch (e) {}
      });
      if (!soon && !live) live = { d: dd, rgb: rgb };
    });
    if (live && !RMQ) {
      var dot = document.createElementNS(NS, 'circle');
      dot.setAttribute('r', '3.2'); dot.setAttribute('fill', '#fff');
      dot.setAttribute('style', 'filter:drop-shadow(0 0 6px rgb(' + live.rgb + '))');
      var mo = document.createElementNS(NS, 'animateMotion');
      mo.setAttribute('dur', '1.6s'); mo.setAttribute('begin', '2.2s;' + 'cyrun.end+3.4s'); mo.setAttribute('id', 'cyrun');
      mo.setAttribute('path', live.d); mo.setAttribute('fill', 'remove');
      dot.appendChild(mo);
      var op = document.createElementNS(NS, 'animate');
      op.setAttribute('attributeName', 'opacity'); op.setAttribute('values', '0;1;1;0'); op.setAttribute('keyTimes', '0;.1;.85;1');
      op.setAttribute('dur', '1.6s'); op.setAttribute('begin', 'cyrun.begin'); op.setAttribute('fill', 'freeze');
      dot.setAttribute('opacity', '0');
      dot.appendChild(op);
      svg.appendChild(dot);
    }
  };
  if (art) {
    drawThreads();
    if (!RMQ) requestAnimationFrame(function () { art.classList.add('drawn'); });
    var rt = 0;
    window.addEventListener('resize', function () { clearTimeout(rt); rt = setTimeout(drawThreads, 150); });
    // images can settle after first layout
    window.addEventListener('load', drawThreads, { once: true });
  }

  /* ---- hero coin: tilts toward the pointer, calmly (no tilt on touch or reduced motion) ---- */
  var coin = document.querySelector('.cy-coin-tilt');
  var hero = document.getElementById('top');
  if (coin && hero && !RMQ && window.matchMedia('(hover: hover)').matches) {
    var raf = 0, tx = 0, ty = 0;
    hero.addEventListener('pointermove', function (e) {
      var b = coin.getBoundingClientRect();
      var nx = Math.max(-1, Math.min(1, (e.clientX - (b.left + b.width / 2)) / (window.innerWidth / 2)));
      var ny = Math.max(-1, Math.min(1, (e.clientY - (b.top + b.height / 2)) / (window.innerHeight / 2)));
      tx = nx * 9; ty = -ny * 7;
      if (!raf) raf = requestAnimationFrame(function () { raf = 0; coin.style.setProperty('--ry', tx.toFixed(2) + 'deg'); coin.style.setProperty('--rx', ty.toFixed(2) + 'deg'); });
    });
    hero.addEventListener('pointerleave', function () { coin.style.setProperty('--ry', '0deg'); coin.style.setProperty('--rx', '0deg'); });
  }

  /* ---- the flow: the step in the middle of the screen is "on" (its visual animates) ---- */
  var steps = Array.prototype.slice.call(document.querySelectorAll('.cy-step'));
  if (steps.length && 'IntersectionObserver' in window) {
    var sio = new IntersectionObserver(function (es) {
      es.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add('seen'); steps.forEach(function (s) { s.classList.toggle('on', s === e.target); }); }
      });
    }, { rootMargin: '-45% 0px -45% 0px', threshold: 0 });
    steps.forEach(function (s) { sio.observe(s); });
    var sio2 = new IntersectionObserver(function (es) { es.forEach(function (e) { if (e.isIntersecting) e.target.classList.add('seen'); }); }, { rootMargin: '0px 0px -20% 0px' });
    steps.forEach(function (s) { sio2.observe(s); });
  } else {
    steps.forEach(function (s) { s.classList.add('seen', 'on'); });
  }
})();

