export const CATEGORY_ICONS: Record<CategoryKey, (p: P) => JSX.Element> = {
  weapons: WeaponsIcon,
  creatures: CreaturesIcon,
  worlds: WorldsIcon,
  mechanics: MechanicsIcon,
  shaders: ShadersIcon,
  magic: MagicIcon,
  quests: QuestsIcon,
  interface: InterfaceIcon,
  audio: AudioIcon,
  vehicles: VehiclesIcon,
  items: ItemsIcon,
  characters: CharactersIcon,
};

/** Renders the icon for a category key. */
export function CategoryIcon({ k, ...props }: { k: CategoryKey } & P) {
  const Icon = CATEGORY_ICONS[k];
  return <Icon {...props} />;
}
import { ToolMount } from "../_components/ToolMount";

/**
 * /tools and /tools/<tool> on the new site. The pages themselves are generated
 * (tools/nxm/port_pages.py: native `tools` hub + `tools-tool` template); this
 * layout only adds the client piece that mounts each live tool component into
 * its page's panel (see ToolMount). On the hub it finds no panel and renders
 * nothing.
 */
export default function NxmToolsLayout({ children }: { children: React.ReactNode }) {
  return (
    <>
      {children}
      <ToolMount />
    </>
  );
}

