      const log = gl.getShaderInfoLog(fs) || gl.getShaderInfoLog(vs) || gl.getProgramInfoLog(prog);
      console.error(`[core:${concept.id}] shader error\n${log}`);
      return false;
    }
    gl.useProgram(prog);
    const buf = gl.createBuffer();
