    gl.uniform1i(u("uSdf"), 0);
    gl.uniform1f(u("uDPU"), DPU);
    gl.uniform1f(u("uSdfK"), SDF_RANGE / 127 / SDF_S / DPU);
    gl.uniform4f(u("uSdfMap"), SDF_S / SDF_W, SDF_S / SDF_H, (SDF_PAD - 20 * SDF_S) / SDF_W, (SDF_PAD - 40 * SDF_S) / SDF_H);
    gl.uniform2f(u("uTexUnits"), SDF_W / SDF_S / DPU, SDF_H / SDF_S / DPU);
    gl.uniform1f(u("uRadius"), 1 / concept.extent);
    U = {
      time: u("uTime"),
      swirl: u("uSwirl"),
      tilt: u("uTilt"),
      tiltX: u("uTiltX"),
      energy: u("uEnergy"),
      pulse: u("uPulse"),
      kick: u("uKick"),
      impulse: u("uImpulse"),
      kicks: u("uKicks"),
      waveR: u("uWaveR"),
      waveS: u("uWaveS"),
      waveAge: u("uWaveAge"),
      waveSeed: u("uWaveSeed"),
      light: u("uLight"),
      px: u("uPx"),
      ready: u("uReady"),
    };
    return true;
  };
  // Without the extension there's nothing to wait for; link (and report errors) now.
  if (!parallel) finish();
  if (failed) return null;

  let devicePx = 1;
  const v4 = (l: WebGLUniformLocation | null, a: number[]) => gl.uniform4f(l, a[0], a[1], a[2], a[3]);

  return {
    resize(cssSize, dpr) {
      const px = Math.max(2, Math.round(cssSize * dpr));
      if (canvas.width !== px) {
        canvas.width = px;
        canvas.height = px;
      }
      canvas.style.width = `${cssSize}px`;
      canvas.style.height = `${cssSize}px`;
      devicePx = px;
      gl.viewport(0, 0, px, px);
    },
    render(f, light) {
      if (gl.isContextLost() || !finish() || !U) return;
      gl.uniform1f(U.time, f.time);
      gl.uniform1f(U.swirl, f.swirl);
      gl.uniform1f(U.tilt, f.tilt);
      gl.uniform1f(U.tiltX, f.tiltX);
      gl.uniform1f(U.energy, f.energy);
      gl.uniform1f(U.pulse, f.pulse);
      gl.uniform1f(U.kick, f.kick);
      gl.uniform1f(U.impulse, f.impulse);
      gl.uniform1f(U.kicks, f.kicks);
      v4(U.waveR, f.waveR);
      v4(U.waveS, f.waveS);
      v4(U.waveAge, f.waveAge);
      v4(U.waveSeed, f.waveSeed);
      gl.uniform1f(U.light, light ? 1 : 0);
      gl.uniform1f(U.px, 2 / devicePx);
      gl.uniform1f(U.ready, ready);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 6);
    },
    ready: () => finish(),
    dispose() {
      window.clearTimeout(build);
      // The canvas is thrown away with the renderer, so releasing the context is safe — but not
      // mid-compile: that blocks until the compile finishes. Wait for it in the background instead.
      const release = () => {
        if (gl.isContextLost()) return;
        if (parallel && !gl.getProgramParameter(prog, parallel.COMPLETION_STATUS_KHR)) {
          window.setTimeout(release, 120);
          return;
        }
        gl.getExtension("WEBGL_lose_context")?.loseContext();
      };
      release();
    },
  };
}
      impulse: st.imp,
      kicks: st.count,
      waveR,
      waveS,
      waveAge,
      waveSeed,
    };
  };
}

/** Typing energy fades on its own; whoever owns the frame loop calls this once per frame. */
export function decayEnergy(dt: number) {
  fx.energy = Math.max(0, fx.energy - dt * 0.5);
}

input.content:
"use client";

/**
 * The Cyrus page's live demo (/cyrus, mounted by ./CyrusPageMount into [data-cyrus-demo]).
 *
 * A real, read-only slice of the studio: the same six game branches and their categories
 * (lib/cyrus/data.ts via the page loader), the REAL Particle Nebula core (coreGL + the
 * particles concept + the core driver + the fx bus, so it reacts to typing exactly like the
 * studio), the studio's build estimate (lib/cyrus/estimate.ts) and token ranges (the live
 * reserve table). What is scripted: the forge itself. Nothing is sent anywhere, nothing is
 * built, nothing is charged, and the card says so.
 *
 * Budget: one WebGL context (the core), created only when the demo is near the viewport;
 * the frame loop stops while off-screen or the tab is hidden; reduced motion = no loop,
 * no camera glide, the core drawn once.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createCoreGL, type CoreGL } from "@/components/cyrus/cosmos/coreGL";
import { particles } from "@/components/cyrus/cosmos/cores/concepts/particles";
import { createCoreDriver, decayEnergy } from "@/components/cyrus/cosmos/cores/driver";
import { inkOf, mix } from "@/components/cyrus/cosmos/color";
import { CATEGORY_ICONS } from "@/components/cyrus/icons/CategoryIcons";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import { fx } from "@/lib/cyrus/fx";
import { estimate, type Complexity } from "@/lib/cyrus/estimate";
import type { CategoryKey, ModelId } from "@/lib/cyrus/types";

export type DemoGame = { id: string; name: string; short: string; rgb: string; logo: string | null; logoTone: string | null; status: "live" | "soon"; categories: string[]; aliases: string[] };
export type DemoCat = { key: string; label: string; rgb: string; keywords: string[] };
export type DemoModel = { id: ModelId; name: string; blurb: string; rgb: string };
export type DemoData = {
  games: DemoGame[];
  categories: DemoCat[];
  models: DemoModel[];
  defaultModel: ModelId;
  reserve: Record<string, Record<Complexity, [number, number]>>;
  stages: { key: string; label: string; sub: string }[];
  starters: { label: string; prompt: string; gameId: string }[];
  mcVersion: string;
  studio?: string;
};

// ---------------------------------------------------------------------------
// Routing: deterministic, in the browser (game names first, then aliases; category keywords)
// ---------------------------------------------------------------------------
const norm = (s: string) => ` ${s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()} `;
const hasWord = (t: string, w: string) => !!w && t.includes(` ${norm(w).trim()} `);

export type Route = { game: DemoGame | null; cat: DemoCat | null; via: "name" | "alias" | null };

export function routePrompt(text: string, games: DemoGame[], cats: DemoCat[]): Route {
  const t = norm(text);
  const first = (words: (g: DemoGame) => string[]) => {
    let best: DemoGame | null = null, at = Infinity;
    for (const g of games) for (const w of words(g)) {
      if (!hasWord(t, w)) continue;
      const i = t.indexOf(` ${norm(w).trim()} `);
      if (i < at) { at = i; best = g; }
    }
    return best;
  };
  let via: Route["via"] = "name";
  let game = first((g) => [g.name, g.short, g.id]);
  if (!game) { game = first((g) => g.aliases); via = game ? "alias" : null; }
  let cat: DemoCat | null = null, score = 0;
  for (const c of cats) {
    let s = 0;
    for (const k of c.keywords) if (hasWord(t, k) || (k.length > 4 && t.includes(` ${k}`))) s += 1;
    if (s && game?.categories.includes(c.key)) s += 0.5;
    if (s > score) { score = s; cat = c; }
  }
  if (game && !cat) cat = cats.find((c) => c.key === game!.categories[0]) ?? null;
  return { game, cat, via };
}

const STOP = new Set(["a", "an", "the", "of", "to", "and", "or", "my", "me", "for", "in", "on", "with", "that", "where", "which", "so", "some", "new", "custom", "cool", "simple"]);
/** A short mod title from the request ("A frost-forged greatsword for Minecraft: …" -> "Frost Forged Greatsword"). */
export function titleFrom(text: string, game: DemoGame | null): string {
  let s = text.trim().replace(/\s+/g, " ");
  s = s.replace(/^(please\s+)?(can you\s+)?(make|build|create|write|give|add)(\s+me)?\s*/i, "");
  s = s.replace(/^(an?|the)\s+/i, "");
  s = s.replace(/^((new|simple|cool|custom)\s+)?(mod|plugin)\s+(for\s+[a-z ]+?\s+)?(that|where|which|with|so)\s+/i, "");
  if (game) for (const w of [game.name, game.short, ...game.aliases]) s = s.replace(new RegExp(`\\b(for|in)\\s+${w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "ig"), "");
  const head = s.split(/[:.,;!?(]|\s(?:that|which|where|with|so|for|to)\s/i)[0] ?? s;
  const words = head.split(/[\s-]+/).filter(Boolean).filter((w, i, a) => !(STOP.has(w.toLowerCase()) && (i === 0 || i === a.length - 1))).slice(0, 4);
  const out = words.map((w) => (/^\//.test(w) ? w : w[0].toUpperCase() + w.slice(1).toLowerCase())).join(" ").replace(/[^A-Za-z0-9 '/]/g, "").trim();
  return out.length >= 3 ? out.slice(0, 40) : "Untitled mod";
}

// ---------------------------------------------------------------------------
// Layout: six games on an ellipse around the core (the studio's clockwise order), three
// categories fanning away from each.
// ---------------------------------------------------------------------------
type N = { id: string; kind: "core" | "game" | "cat" | "mod"; x: number; y: number; rgb: string; parent?: string; side?: "left" | "right"; game?: DemoGame; cat?: DemoCat; label?: string };
const ANGLES6 = [-120, -60, 0, 55, 125, 180];
const CORE_R = 100;

function layout(games: DemoGame[], cats: DemoCat[], narrow: boolean) {
  const rx = narrow ? 230 : 520, ry = narrow ? 330 : 300, cd = narrow ? 125 : 150;
  const catBy = new Map(cats.map((c) => [c.key, c]));
  const nodes: N[] = [{ id: "core", kind: "core", x: 0, y: 0, rgb: "167 139 250" }];
  games.forEach((g, i) => {
    const deg = games.length === 6 ? ANGLES6[i] : -90 + (i * 360) / games.length;
    const th = (deg * Math.PI) / 180;
    const gx = Math.cos(th) * rx, gy = Math.sin(th) * ry;
    nodes.push({ id: g.id, kind: "game", x: gx, y: gy, rgb: g.rgb, parent: "core", game: g });
    g.categories.slice(0, 3).forEach((k, j) => {
      const c = catBy.get(k);
      if (!c) return;
      const a = th + (j - 1) * (narrow ? 0.7 : 0.62);
      const cx = gx + Math.cos(a) * cd, cy = gy + Math.sin(a) * cd * (narrow ? 1 : 0.85);
      nodes.push({ id: `${g.id}:${k}`, kind: "cat", x: cx, y: cy, rgb: g.rgb, parent: g.id, side: cx < gx - 4 ? "left" : "right", game: g, cat: c });
    });
  });
  return { nodes, rx, ry, cd };
}

type Link = { a: N; b: N; kind: "game" | "cat" | "mod" };
type Packet = { path: string[]; seg: number; t: number; speed: number; rgb: string; size: number; ambient: boolean };
type Cam = { x: number; y: number; k: number };

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
function cubic(p: number[], t: number) {
  const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
  return { x: a * p[0] + b * p[2] + c * p[4] + d * p[6], y: a * p[1] + b * p[3] + c * p[5] + d * p[7] };
}

type Phase = "idle" | "clarify" | "routing" | "forging" | "done";
type Job = { prompt: string; title: string; game: DemoGame; cat: DemoCat; model: ModelId; complexity: Complexity; tokens: [number, number]; features: string[]; commands: string[]; stage: number };

export default function CyrusDemo({ data, pageEl }: { data: DemoData; pageEl: HTMLElement | null }) {
  const stageRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const coreRef = useRef<HTMLCanvasElement | null>(null);
  const nodeEls = useRef(new Map<string, HTMLDivElement>());
  const [size, setSize] = useState({ w: 0, h: 0 });
  const [dark, setDark] = useState(true);
  const [text, setText] = useState("");
  const [model, setModel] = useState<ModelId>(data.defaultModel);
  const [phase, setPhase] = useState<Phase>("idle");
  const [job, setJob] = useState<Job | null>(null);
  const [focus, setFocus] = useState<string | null>(null);
  const [hits, setHits] = useState<Set<string>>(new Set());
  const [cardOpen, setCardOpen] = useState(false);
  const [pending, setPending] = useState<string | null>(null);
  const reduced = useRef(false);
  const run = useRef(0);

  const narrow = size.w > 0 && size.w < 700;
  const L = useMemo(() => layout(data.games, data.categories, narrow), [data.games, data.categories, narrow]);
  const modNode: N | null = useMemo(() => {
    if (!job) return null;
    const c = L.nodes.find((n) => n.id === `${job.game.id}:${job.cat.key}`);
    if (!c) return null;
    const g = L.nodes.find((n) => n.id === job.game.id)!;
    const dir = c.x >= g.x ? 1 : -1;
    return { id: "mod", kind: "mod", x: c.x + dir * 58, y: c.y + 40, rgb: job.game.rgb, parent: c.id, side: dir > 0 ? "right" : "left", label: job.title };
  }, [job, L]);
  const nodes = useMemo(() => (modNode ? [...L.nodes, modNode] : L.nodes), [L, modNode]);

  // live preview of the route + estimate while typing (zero cost, all local)
  const preview = useMemo(() => {
    if (!text.trim()) return null;
    const r = routePrompt(text, data.games, data.categories);
    const e = estimate(text, model);
    const rng = data.reserve[model]?.[e.complexity] ?? null;
    return { r, e, rng };
  }, [text, model, data]);

  // ---- theme follows the page ----
  useEffect(() => {
    reduced.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const el = pageEl;
    const read = () => setDark((el?.getAttribute("data-cy-theme") ?? "dark") !== "light");
    read();
    if (!el) return;
    const mo = new MutationObserver(read);
    mo.observe(el, { attributes: true, attributeFilter: ["data-cy-theme"] });
    return () => mo.disconnect();
  }, [pageEl]);

  // ---- size ----
  useEffect(() => {
    const el = stageRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setSize({ w: el.clientWidth, h: el.clientHeight }));
    ro.observe(el);
    setSize({ w: el.clientWidth, h: el.clientHeight });
    return () => ro.disconnect();
  }, []);

  // ---- the render loop (canvas links/packets, the WebGL core, DOM node positions) ----
  const st = useRef({ cam: { x: 0, y: 0, k: 0.5 } as Cam, target: { x: 0, y: 0, k: 0.5 } as Cam, packets: [] as Packet[], ripples: [] as number[], last: 0, visible: false, raf: 0, ambientAt: 0, dirty: true, stream: null as string[] | null });
  const fitK = useCallback((w: number, h: number) => {
    if (!w || !h) return 0.5;
    const ext = narrow ? { x: L.rx + 70, y: L.ry + 80 } : { x: L.rx + L.cd + 120, y: L.ry + L.cd * 0.85 + 50 };
    return Math.min(w / (2 * ext.x), h / (2 * ext.y));
  }, [L, narrow]);

  // camera target from focus
  useEffect(() => {
    const s = st.current;
    const k0 = fitK(size.w, size.h);
    if (!focus) s.target = { x: 0, y: 0, k: k0 };
    else {
      const g = L.nodes.find((n) => n.id === focus);
      if (g) {
        const kids = nodes.filter((n) => n.parent === g.id || n.id === "mod");
        const xs = [g.x, ...kids.map((n) => n.x)], ys = [g.y, ...kids.map((n) => n.y)];
        const cx = (Math.min(...xs) + Math.max(...xs)) / 2, cy = (Math.min(...ys) + Math.max(...ys)) / 2;
        const spanX = Math.max(...xs) - Math.min(...xs) + (narrow ? 260 : 420), spanY = Math.max(...ys) - Math.min(...ys) + 220;
        const k = clamp(Math.min(size.w / spanX, size.h / spanY), k0, k0 * (narrow ? 2.1 : 1.7));
        // keep a bit of the core in view on wide stages: pull the centre toward it
        const pull = narrow ? 0.12 : 0.28;
        s.target = { x: cx * (1 - pull), y: cy * (1 - pull), k };
      }
    }
    if (reduced.current || s.cam.k === 0.5) s.cam = { ...s.target };
    s.dirty = true;
  }, [focus, size, L, nodes, fitK, narrow]);

  useEffect(() => {
    const stage = stageRef.current, canvas = canvasRef.current;
    if (!stage || !canvas || !size.w) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const s = st.current;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(size.w * dpr);
    canvas.height = Math.round(size.h * dpr);
    canvas.style.width = `${size.w}px`;
    canvas.style.height = `${size.h}px`;

    // the one WebGL context: the core
    let core: CoreGL | null = null;
    const glc = document.createElement("canvas");
    glc.className = "cyd-core";
    glc.setAttribute("aria-hidden", "true");
    stage.insertBefore(glc, stage.firstChild?.nextSibling ?? null);
    coreRef.current = glc;
    try { core = createCoreGL(glc, particles); } catch { core = null; }
    const onLost = (e: Event) => { e.preventDefault(); core = null; glc.style.visibility = "hidden"; };
    glc.addEventListener("webglcontextlost", onLost);
    const driver = createCoreDriver();
    let glSize = 0;

    const byId = new Map(nodes.map((n) => [n.id, n]));
    const links: Link[] = nodes.filter((n) => n.parent).map((n) => ({ a: byId.get(n.parent!)!, b: n, kind: n.kind === "game" ? "game" : n.kind === "cat" ? "cat" : "mod" }));
    const pairs = new Map(links.map((l) => [`${l.a.id}|${l.b.id}`, l]));
    const curves = new Map<Link, number[]>();

    const toScreen = (x: number, y: number) => ({ x: size.w / 2 + (x - s.cam.x) * s.cam.k, y: size.h / 2 + (y - s.cam.y) * s.cam.k });
    const radius = (n: N) => (n.kind === "core" ? CORE_R : n.kind === "game" ? 54 : n.kind === "cat" ? 20 : 0);
    const col = (rgb: string) => (dark ? rgb : inkOf(rgb));

    const frame = (now: number) => {
      const dt = Math.min(0.05, s.last ? (now - s.last) / 1000 : 0.016);
      s.last = now;
      // camera glide
      const e = reduced.current ? 1 : 1 - Math.pow(0.0025, dt);
      s.cam.x += (s.target.x - s.cam.x) * e;
      s.cam.y += (s.target.y - s.cam.y) * e;
      s.cam.k += (s.target.k - s.cam.k) * e;
      const k = s.cam.k;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size.w, size.h);
      const px = 1;
      // links: smooth S-curves, a soft glow and a bright core line (the studio's look)
      for (const l of links) {
        const A0 = toScreen(l.a.x, l.a.y), B0 = toScreen(l.b.x, l.b.y);
        const dx = B0.x - A0.x, dy = B0.y - A0.y, len = Math.hypot(dx, dy) || 1;
        const ra = radius(l.a) * k, rb = l.kind === "mod" ? 0 : radius(l.b) * k;
        const A = { x: A0.x + (dx / len) * ra, y: A0.y + (dy / len) * ra }, B = { x: B0.x - (dx / len) * rb, y: B0.y - (dy / len) * rb };
        const p = [A.x, A.y, 0, 0, 0, 0, B.x, B.y];
        if (l.kind === "game") {
          const al = Math.hypot(A.x - toScreen(0, 0).x, A.y - toScreen(0, 0).y) || 1;
          const ox = (A.x - toScreen(0, 0).x) / al, oy = (A.y - toScreen(0, 0).y) / al;
          p[2] = A.x + ox * len * 0.42; p[3] = A.y + oy * len * 0.42;
          const horiz = Math.abs(dx) > Math.abs(dy) * 0.8;
          p[4] = horiz ? B.x - dx * 0.45 : B.x; p[5] = horiz ? B.y : B.y - dy * 0.45;
        } else {
          const horiz = Math.abs(dx) >= Math.abs(dy) * 0.7;
          p[2] = horiz ? A.x + dx * 0.5 : A.x; p[3] = horiz ? A.y : A.y + dy * 0.5;
          p[4] = horiz ? B.x - dx * 0.5 : B.x; p[5] = horiz ? B.y : B.y - dy * 0.5;
        }
        curves.set(l, p);
        const dim = focus && l.b.id !== focus && l.a.id !== focus && !(l.kind === "mod") && !(l.kind === "game" && l.b.id === focus) ? 0.25 : 1;
        const streaming = !!s.stream && s.stream.includes(l.a.id) && s.stream.includes(l.b.id);
        const base = l.kind === "game" ? 2.1 : l.kind === "cat" ? 1.6 : 1.1;
        const boost = streaming ? 2.2 : 1;
        const g = ctx.createLinearGradient(A.x, A.y, B.x, B.y);
        g.addColorStop(0, `rgb(${col(l.kind === "game" ? mix(l.b.rgb, 0.35) : l.b.rgb)})`);
        g.addColorStop(1, `rgb(${col(l.b.rgb)})`);
        ctx.strokeStyle = g;
        ctx.beginPath(); ctx.moveTo(p[0], p[1]); ctx.bezierCurveTo(p[2], p[3], p[4], p[5], p[6], p[7]);
        ctx.globalAlpha = clamp((dark ? 0.14 : 0.08) * boost * dim, 0, 0.6);
        ctx.lineWidth = base * (dark ? 5 : 3.5) * Math.min(boost, 2.2);
        ctx.stroke();
        ctx.globalAlpha = clamp((dark ? 0.85 : 0.75) * Math.min(boost, 1.6) * dim, 0, 1);
        ctx.lineWidth = Math.max(base * (streaming ? 1.5 : 1), 0.8 * px);
        ctx.stroke();
        if (streaming && !reduced.current) {
          ctx.globalAlpha = dark ? 0.9 : 0.7;
          ctx.strokeStyle = dark ? "rgb(255 255 255)" : `rgb(${col(l.b.rgb)})`;
          ctx.lineWidth = 1; ctx.setLineDash([4, 10]); ctx.lineDashOffset = -now / 1000 * 90; ctx.stroke(); ctx.setLineDash([]);
        }
        // beads
        for (const bt of l.kind === "game" ? [0.3, 0.62] : l.kind === "cat" ? [0.5] : []) {
          const q = cubic(p, bt);
          ctx.globalAlpha = 0.3 * dim; ctx.fillStyle = `rgb(${col(l.b.rgb)})`;
          ctx.beginPath(); ctx.arc(q.x, q.y, 6, 0, Math.PI * 2); ctx.fill();
          ctx.globalAlpha = dim; ctx.fillStyle = dark ? `rgb(${mix(l.b.rgb, 0.65)})` : `rgb(${col(l.b.rgb)})`;
          ctx.beginPath(); ctx.arc(q.x, q.y, 2.3, 0, Math.PI * 2); ctx.fill();
        }
      }
      ctx.globalAlpha = 1;

      // ambient packets now and then (the studio's idle traffic)
      if (!reduced.current && now - s.ambientAt > 1700 && s.packets.length < 6) {
        s.ambientAt = now;
        const gs = nodes.filter((n) => n.kind === "game");
        const g = gs[Math.floor(Math.random() * gs.length)];
        if (g) s.packets.push({ path: ["core", g.id], seg: 0, t: 0, speed: 0.7, rgb: g.rgb, size: 0.8, ambient: true });
      }
      for (let i = s.packets.length - 1; i >= 0; i--) {
        const pk = s.packets[i];
        const l = pairs.get(`${pk.path[pk.seg]}|${pk.path[pk.seg + 1]}`) ?? pairs.get(`${pk.path[pk.seg + 1]}|${pk.path[pk.seg]}`);
        const p = l && curves.get(l);
        if (!l || !p) { s.packets.splice(i, 1); continue; }
        const fwd = l.a.id === pk.path[pk.seg];
        const len = Math.hypot(p[6] - p[0], p[7] - p[1]) * 1.1 + 1;
        pk.t += (dt * pk.speed * 300) / len;
        if (pk.t >= 1) { pk.seg++; pk.t = 0; if (pk.seg >= pk.path.length - 1) s.packets.splice(i, 1); continue; }
        const at = (tt: number) => cubic(p, fwd ? tt : 1 - tt);
        const c = dark ? pk.rgb : inkOf(pk.rgb);
        const alpha = pk.ambient ? 0.55 : 1;
        const head = at(pk.t);
        let prev = head;
        for (let j = 1; j <= 7; j++) {
          const tt = pk.t - (j / 7) * 0.22;
          if (tt < 0) break;
          const pt = at(tt);
          ctx.strokeStyle = `rgb(${c} / ${alpha * (1 - j / 7) * 0.85})`;
          ctx.lineWidth = pk.size * 1.8 * (1 - j / 8);
          ctx.beginPath(); ctx.moveTo(prev.x, prev.y); ctx.lineTo(pt.x, pt.y); ctx.stroke();
          prev = pt;
        }
        ctx.fillStyle = `rgb(${c} / ${alpha * 0.25})`; ctx.beginPath(); ctx.arc(head.x, head.y, pk.size * 4.5, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = dark ? `rgb(255 255 255 / ${alpha})` : `rgb(${c} / ${alpha})`; ctx.beginPath(); ctx.arc(head.x, head.y, pk.size * 1.3, 0, Math.PI * 2); ctx.fill();
      }

      // ripples off the core rim
      const o = toScreen(0, 0);
      for (let i = s.ripples.length - 1; i >= 0; i--) {
        const age = (now - s.ripples[i]) / 1000;
        if (age > 1.6) { s.ripples.splice(i, 1); continue; }
        const q = age / 1.6, ez = 1 - Math.pow(1 - q, 3);
        ctx.strokeStyle = dark ? `rgb(196 181 253 / ${(1 - q) * 0.6})` : `rgb(109 74 224 / ${(1 - q) * 0.45})`;
        ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(o.x, o.y, (CORE_R + 4 + ez * 110) * k, 0, Math.PI * 2); ctx.stroke();
      }

      // the core (WebGL), drawn in screen space so it stays sharp at any zoom
      const coreSize = 2 * CORE_R * particles.extent * k;
      if (core) {
        if (Math.abs(coreSize - glSize) > 0.5) {
          glSize = coreSize;
          core.resize(coreSize, Math.max(1, Math.min(window.devicePixelRatio || 1, 2, 1600 / Math.max(coreSize, 1))));
        }
        glc.style.transform = `translate3d(${(o.x - coreSize / 2).toFixed(1)}px, ${(o.y - coreSize / 2).toFixed(1)}px, 0)`;
        core.render(driver(now, dt), !dark);
      } else {
        // no WebGL: a quiet gradient sphere so the core never disappears
        const R = CORE_R * k;
        const body = ctx.createRadialGradient(o.x - R * 0.25, o.y - R * 0.35, R * 0.1, o.x, o.y, R);
        body.addColorStop(0, dark ? "rgb(60 46 160)" : "rgb(255 255 255)"); body.addColorStop(1, dark ? "rgb(8 6 26)" : "rgb(214 204 253)");
        ctx.fillStyle = body; ctx.beginPath(); ctx.arc(o.x, o.y, R, 0, Math.PI * 2); ctx.fill();
      }
      decayEnergy(dt);

      // DOM nodes follow the camera
      for (const n of nodes) {
        const el = nodeEls.current.get(n.id);
        if (!el) continue;
        const q = toScreen(n.x, n.y);
        el.style.transform = `translate3d(${q.x.toFixed(1)}px, ${(q.y + (n.kind === "core" ? CORE_R * k + 10 : 0)).toFixed(1)}px, 0)`;
        if (n.kind === "game") el.style.setProperty("--sz", `${clamp(108 * k, 40, 76).toFixed(0)}px`);
      }
    };

    const loop = (now: number) => {
      s.raf = 0;
      frame(now);
      if (s.visible && !reduced.current && !document.hidden) s.raf = requestAnimationFrame(loop);
    };
    const kick = () => {
      if (s.raf) return;
      if (reduced.current) {
        // reduced motion: a few frames to settle the core and the camera, then stop
        let n = 0;
        const step = (t: number) => { frame(t); if (++n < 3) requestAnimationFrame(step); };
        requestAnimationFrame(step);
        return;
      }
      if (s.visible && !document.hidden) s.raf = requestAnimationFrame(loop);
    };
    const io = new IntersectionObserver((es) => { s.visible = es.some((e) => e.isIntersecting); s.last = 0; kick(); }, { rootMargin: "120px" });
    io.observe(stage);
    const onVis = () => { s.last = 0; kick(); };
    document.addEventListener("visibilitychange", onVis);
    (s as unknown as { kick: () => void }).kick = kick;
    kick();
    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      if (s.raf) cancelAnimationFrame(s.raf);
      s.raf = 0;
      glc.removeEventListener("webglcontextlost", onLost);
      core?.dispose();
      glc.remove();
      coreRef.current = null;
    };
  }, [size, nodes, dark, focus]);

  const kickLoop = () => (st.current as unknown as { kick?: () => void }).kick?.();

  // ---- the scripted forge ----
  const forge = useCallback(async (prompt: string, forcedGame?: DemoGame) => {
    const id = ++run.current;
    const s = st.current;
    const alive = () => run.current === id;
    const r = routePrompt(prompt, data.games, data.categories);
    const game = forcedGame ?? r.game;
    setCardOpen(false);
    setHits(new Set());
    if (!game) { setPending(prompt); setPhase("clarify"); setFocus(null); return; }
    setPending(null);
    const cat = (r.cat && game.categories.includes(r.cat.key) ? r.cat : null) ?? data.categories.find((c) => c.key === game.categories[0])!;
    const e = estimate(prompt, model);
    const commands = [...new Set((prompt.match(/\/[a-z][a-z0-9_-]{1,24}/gi) || []).map((c) => c.toLowerCase()))].slice(0, 3);
    const j: Job = { prompt, title: titleFrom(prompt, game), game, cat, model, complexity: e.complexity, tokens: data.reserve[model]?.[e.complexity] ?? [0, 0], features: e.features, commands, stage: -1 };
    const slow = reduced.current ? 0.15 : 1;
    setJob(null);
    setPhase("routing");
    fx.setMode("thinking");
    s.ripples.push(performance.now());
    fx.kick();
    kickLoop();
    await sleep(650 * slow); if (!alive()) return;
    setFocus(game.id);
    s.packets.push({ path: ["core", game.id], seg: 0, t: 0, speed: 1.3, rgb: game.rgb, size: 1.2, ambient: false });
    s.stream = ["core", game.id];
    setHits(new Set([game.id]));
    await sleep(800 * slow); if (!alive()) return;
    setJob(j);
    const cid = `${game.id}:${cat.key}`;
    s.stream = ["core", game.id, cid, "mod"];
    s.packets.push({ path: ["core", game.id, cid], seg: 0, t: 0, speed: 1.4, rgb: game.rgb, size: 1.2, ambient: false });
    setHits(new Set([game.id, cid]));
    setPhase("forging");
    fx.setMode("forging");
    setCardOpen(true);
    const steps = game.status === "live" ? data.stages.length : 2;
    for (let i = 0; i < steps; i++) {
      setJob((x) => (x ? { ...x, stage: i } : x));
      if (i > 0) { s.packets.push({ path: [game.id, cid, "mod"], seg: 0, t: 0, speed: 1.6, rgb: game.rgb, size: 1, ambient: false }); fx.kick(); }
      await sleep((data.stages[i]?.key === "repairing" ? 350 : 820) * slow); if (!alive()) return;
    }
    setJob((x) => (x ? { ...x, stage: steps } : x));
    s.stream = null;
    fx.setMode("idle");
    s.ripples.push(performance.now());
    setPhase("done");
    kickLoop();
  }, [data, model]);

  useEffect(() => () => { run.current++; fx.setMode("idle"); }, []);

  const submit = () => { const t = text.trim(); if (t) void forge(t); };
  const reset = () => { run.current++; setPhase("idle"); setJob(null); setFocus(null); setHits(new Set()); setCardOpen(false); st.current.stream = null; fx.setMode("idle"); };

  const catBy = useMemo(() => new Map(data.categories.map((c) => [c.key, c])), [data.categories]);
  const recommended = preview?.e.recommended;
  const modelName = (id: string) => data.models.find((m) => m.id === id)?.name ?? id;

  const Icon = ({ k }: { k: string }) => {
    const C = CATEGORY_ICONS[k as CategoryKey];
    return C ? <C /> : null;
  };
  const Logo = ({ g, size: sz }: { g: DemoGame; size?: number }) => (
    <span className={`cy-logo${g.logoTone === "light" ? " is-light" : ""}`} style={{ ["--g" as string]: g.rgb, ...(sz ? { width: sz, height: sz } : {}) }}>
      {g.logo ? <img src={g.logo} alt="" width={64} height={64} decoding="async" /> : null}
    </span>
  );

  const stageLabel = (i: number) => {
    if (!job) return "";
    if (job.stage > i) return data.stages[i]?.key === "repairing" ? "not needed" : "done";
    if (job.stage === i) return "now";
    return "";
  };

  return (
    <div className="cyd">
      <div className="cyd-stage" ref={stageRef} aria-label="Cyrus network map (demo)" role="img">
        <canvas className="cyd-canvas" ref={canvasRef} aria-hidden="true" />
        <div className="cyd-nodes">
          {nodes.map((n) => {
            const set = (el: HTMLDivElement | null) => { if (el) nodeEls.current.set(n.id, el); else nodeEls.current.delete(n.id); };
            const off = !!focus && n.kind !== "core" && n.id !== focus && n.parent !== focus && n.kind !== "mod";
            if (n.kind === "core") return (
              <div key={n.id} ref={set} className="cyd-node"><span className="cyd-corelabel"><i />{phase === "routing" ? "routing" : phase === "forging" ? "forging" : "online"}</span></div>
            );
            if (n.kind === "game") {
              const g = n.game!;
              return (
                <div key={n.id} ref={set} className={`cyd-node${off ? " off" : ""}`}>
                  <div className={`cyd-game${hits.has(n.id) ? " hit" : ""}`} style={{ ["--g" as string]: g.rgb }}>
                    <button type="button" tabIndex={-1} aria-hidden="true" onClick={() => { setFocus(focus === g.id ? null : g.id); kickLoop(); }}><Logo g={g} /></button>
                    <span className="cyd-gname">{g.short}<em className={g.status === "live" ? "live" : ""}>{g.status === "live" ? "Live" : "Soon"}</em></span>
                  </div>
                </div>
              );
            }
            if (n.kind === "cat") {
              if (narrow && focus !== n.parent) return null;
              return (
                <div key={n.id} ref={set} className={`cyd-node${off ? " off" : ""}`}>
                  <div className={`cyd-cat${hits.has(n.id) ? " hit" : ""}`} data-side={n.side} style={{ ["--g" as string]: n.rgb }}>
                    <span className="cyd-corb"><Icon k={n.cat!.key} /></span><span className="cyd-clabel">{n.cat!.label}</span>
                  </div>
                </div>
              );
            }
            return (
              <div key={n.id} ref={set} className="cyd-node">
                <span className={`cyd-pill${phase === "forging" ? " forging" : ""}`} data-side={n.side} style={{ ["--g" as string]: n.rgb }}><i />{n.label}<small>demo</small></span>
              </div>
            );
          })}
        </div>

        <aside className="cyd-card" hidden={!cardOpen || !job} aria-live="polite">
          {job && (
            <>
              <button type="button" className="cyd-x" onClick={reset} aria-label="Close and reset the demo">×</button>
              <p className="cyd-card-k">Demo · scripted sample</p>
              <h3>{job.title}</h3>
              <p>{job.game.name} › {job.cat.label}</p>
              <dl className="cyd-facts">
                <div><dt>Model</dt><dd><span className="cy-mg sm" style={{ color: `rgb(${data.models.find((m) => m.id === job.model)?.rgb ?? "167 139 250"})` }}><ModelGlyph id={job.model} /></span>{modelName(job.model)}</dd></div>
                <div><dt>Size</dt><dd>{job.complexity}</dd></div>
                <div><dt>Estimate</dt><dd>{job.tokens[0]}–{job.tokens[1]} tokens</dd></div>
                <div><dt>Target</dt><dd>{job.game.status === "live" ? `Paper ${data.mcVersion}` : "Template preview"}</dd></div>
              </dl>
              <ol className="cyd-steps">
                {(job.game.status === "live" ? data.stages : data.stages.slice(0, 2)).map((sg, i) => {
                  const lab = stageLabel(i);
                  return <li key={sg.key} className={job.stage > i ? (sg.key === "repairing" ? "done skip" : "done") : job.stage === i ? "on" : ""}><i /><span>{sg.label}</span><small>{lab === "now" ? sg.sub : lab}</small></li>;
                })}
              </ol>
              {job.stage >= (job.game.status === "live" ? data.stages.length : 2) && (job.game.status === "live" ? (
                <pre className="cyd-code">{`name: ${job.title.replace(/[^A-Za-z0-9]/g, "") || "CyrusMod"}
version: 1.0.0
api-version: '${data.mcVersion.split(".").slice(0, 2).join(".")}'
${job.commands.length ? `commands:\n${job.commands.map((c) => `  ${c.slice(1)}:\n    usage: ${c}`).join("\n")}` : "description: Built by Cyrus"}`}</pre>
              ) : (
                <span className="cyd-note soon">{job.game.name} is in development: in the studio Cyrus drafts this as a template preview. It is not compiled or installable yet.</span>
              ))}
              <span className="cyd-note">Scripted sample. In the studio, Cyrus writes, compiles and safety-checks the real files{job.features.length ? `; it would plan for ${job.features.slice(0, 3).join(", ")}` : ""}.</span>
            </>
          )}
        </aside>
      </div>

      <div className="cyd-dockwrap">
        <form className="cyd-dock" onSubmit={(e) => { e.preventDefault(); submit(); }}>
          <p className="cyd-route" aria-live="polite">
            <i aria-hidden="true" />
            {phase === "clarify" ? <>Which game is this for? Cyrus asks instead of guessing.</>
              : preview?.r.game ? <>Routes to <b>{preview.r.game.name}</b>{preview.r.cat ? <> › <b>{preview.r.cat.label}</b></> : null}{preview.r.game.status === "soon" ? " · template preview" : ""}</>
              : text.trim() ? <>No game named yet. Cyrus will ask which one.</>
              : <>Auto-route through the core: name a game, or pick an idea below.</>}
          </p>
          {phase === "clarify" && (
            <div className="cyd-clarify">
              {data.games.map((g) => (
                <button key={g.id} type="button" onClick={() => pending && void forge(pending, g)}><Logo g={g} />{g.short}</button>
              ))}
            </div>
          )}
          <label className="sr-only" htmlFor="cyd-in">Describe a mod</label>
          <textarea
            id="cyd-in"
            className="cyd-in"
            rows={2}
            maxLength={400}
            placeholder="Describe a mod, e.g. a Minecraft shop where coins drop from mobs…"
            value={text}
            onChange={(e) => { setText(e.target.value); fx.keystroke(1); kickLoop(); }}
            onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); submit(); } }}
          />
          <div className="cyd-bar">
            <div className="cyd-models" role="group" aria-label="Model">
              {data.models.map((m) => (
                <button key={m.id} type="button" aria-pressed={model === m.id} onClick={() => setModel(m.id)} style={{ ["--m" as string]: m.rgb }} title={m.blurb}>
                  <span className="cy-mg sm"><ModelGlyph id={m.id} /></span><span className="n">{m.name}</span>
                </button>
              ))}
            </div>
            <span className="cyd-est">{preview?.rng ? <>Estimate <b>{preview.rng[0]}–{preview.rng[1]}</b> tokens · {preview.e.complexity}{recommended && recommended !== model ? <> · {modelName(recommended)} suggested</> : null}</> : <>Estimate appears as you type</>}</span>
            <button type="submit" className="cyd-go" disabled={!text.trim() || phase === "routing" || phase === "forging"}>Forge sample</button>
          </div>
        </form>
        <div className="cyd-chips">
          <span>Try</span>
          {data.starters.map((s) => {
            const g = data.games.find((x) => x.id === s.gameId);
            return (
              <button key={s.label} type="button" onClick={() => { setText(s.prompt); void forge(s.prompt); }}>
                {g ? <Logo g={g} /> : null}{s.label}
              </button>
            );
          })}
        </div>
      </div>
      {catBy.size === 0 ? null : null}
    </div>
  );
}

