"use client";

import dynamic from "next/dynamic";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { CATEGORY_ICONS } from "@/components/cyrus/icons/CategoryIcons";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import type { CategoryKey, ModelId } from "@/lib/cyrus/types";
import type { DemoData } from "./CyrusDemo";

/**
 * The Cyrus page's React pieces, mounted into its server-rendered design markup
 * (tools/nxm/native/cyrus, the same technique as app/nxm/_components/ToolMount.tsx):
 *  - every `[data-cy-icon="cat:<key>" | "model:<id>"]` placeholder gets the studio's own icon
 *    (components/cyrus/icons: CategoryIcons, ModelGlyphs), so the page always shows the same
 *    marks as the studio;
 *  - `[data-cyrus-demo]` gets the live demo, loaded as its own chunk only when the section
 *    comes near the viewport (it carries the WebGL core).
 * The page data is the loader's `#nxm-data` JSON (app/nxm/_data/cyrus.ts).
 */
const CyrusDemo = dynamic(() => import("./CyrusDemo"), { ssr: false });

type IconSlot = { el: HTMLElement; kind: "cat" | "model"; id: string };

function readData(): DemoData | null {
  try {
    const raw = document.getElementById("nxm-data")?.textContent;
    return raw ? (JSON.parse(raw) as DemoData) : null;
  } catch {
    return null;
  }
}

export function CyrusPageMount() {
  const pathname = usePathname();
  const [icons, setIcons] = useState<IconSlot[]>([]);
  const [demo, setDemo] = useState<{ host: HTMLElement; data: DemoData; page: HTMLElement | null } | null>(null);

  useEffect(() => {
    let io: IntersectionObserver | null = null;
    let mo: MutationObserver | null = null;
    let layer: HTMLElement | null = null;
    const attach = () => {
      const page = document.querySelector<HTMLElement>(".nxm-p-cyrus");
      if (!page) return false;
      setIcons(
        Array.from(page.querySelectorAll<HTMLElement>("[data-cy-icon]")).flatMap((el) => {
          const [kind, id] = (el.dataset.cyIcon ?? "").split(":");
          return kind === "cat" || kind === "model" ? [{ el, kind, id } as IconSlot] : [];
        }),
      );
      const host = page.querySelector<HTMLElement>("[data-cyrus-demo]");
      const data = readData();
      if (host && data) {
        const start = () => {
          if (layer) return;
          layer = document.createElement("div");
          layer.className = "cyd-mount";
          host.appendChild(layer);
          host.classList.add("on");
          const studio = page.querySelector<HTMLAnchorElement>(".cy-ctas a")?.getAttribute("href") ?? undefined;
          setDemo({ host: layer, data: { ...data, studio }, page });
        };
        if ("IntersectionObserver" in window) {
          io = new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) { io?.disconnect(); start(); } }, { rootMargin: "400px 0px" });
          io.observe(host);
        } else start();
      }
      return true;
    };
    if (!attach()) {
      mo = new MutationObserver(() => { if (attach()) mo?.disconnect(); });
      mo.observe(document.body, { childList: true, subtree: true });
    }
    return () => {
      io?.disconnect();
      mo?.disconnect();
      layer?.parentElement?.classList.remove("on");
      layer?.remove();
      setDemo(null);
      setIcons([]);
    };
  }, [pathname]);

  return (
    <>
      {icons.map((s, i) => {
        if (s.kind === "cat") {
          const C = CATEGORY_ICONS[s.id as CategoryKey];
          return C ? createPortal(<C />, s.el, `i${i}`) : null;
        }
        return ["katara", "saka", "yakko"].includes(s.id) ? createPortal(<ModelGlyph id={s.id as ModelId} />, s.el, `i${i}`) : null;
      })}
      {demo && createPortal(<CyrusDemo data={demo.data} pageEl={demo.page?.closest<HTMLElement>(".nxm-p") ?? demo.page} />, demo.host)}
    </>
  );
}

