  assert.equal(await cyrusPublicEnabled(), false);
  assert.deepEqual(await cyrusPageAccessFor({ email: "nicholas.sj.albanese@gmail.com" }), { allowed: false, isPublic: false, preview: false });
  assert.equal((await cyrusPageAccessFor(null)).allowed, false);
  await assert.rejects(requireCyrusPageAccess(), (e: unknown) => {
    const digest = String((e as { digest?: string })?.digest ?? (e as Error)?.message ?? "");
    return /NEXT_HTTP_ERROR_FALLBACK;404|NEXT_NOT_FOUND/.test(digest);
  });
});

test("the flag defaults to OFF and the preview audience is the studio's (modbuilder)", () => {
  assert.match(read("lib/settings.ts"), /cyrus_public_enabled:\s*"false"/);
  assert.match(read("lib/cyrus/public-gate.ts"), /isPreviewUser\(user, "modbuilder"\)/);
});

test("the page loader calls the gate before anything else, and is noindex unless public", () => {
  const src = read("app/nxm/_data/cyrus.ts");
  const body = src.slice(src.indexOf("export async function load"));
  const firstAwait = /await\s+([A-Za-z]+)\(/.exec(body);
  assert.equal(firstAwait?.[1], "requireCyrusPageAccess", "the gate must be the first await in load()");
  assert.match(src, /noindex: !on/);
  const route = read("app/nxm/cyrus/page.tsx");
  assert.match(route, /import \{ load, meta \} from "..\/_data\/cyrus"/);
  assert.match(route, /await load\(p\)/);
});

test("not in the sitemap while off", () => {
  const sections = read("lib/sitemap-sections.ts");
  const staticBlock = sections.slice(sections.indexOf("export const STATIC_PATHS"), sections.indexOf("];", sections.indexOf("export const STATIC_PATHS")));
  assert.ok(!staticBlock.includes('"/cyrus"'));
  assert.match(sections, /const EXCLUDE = new Set<string>\(\[[^\]]*CYRUS_PAGE_PATH/);
  assert.match(sections, /cyrusPageSitemapPaths\(await cyrusPublicEnabled\(\)\)/);
  // the NXM site serves /cyrus (live-routes.json), the middleware routes it there
  const live = JSON.parse(read("app/nxm/_data/live-routes.json")) as { exact: string[] };
  assert.ok(live.exact.includes("/cyrus"));
});

test("NXM nav + footer: the Cyrus entries are injected only for viewers who pass the gate", async () => {
  const { withCyrusNav, cyrusFooterLinks, CYRUS_FOOTER_LINK } = await import("../app/nxm/_components/cyrus-nav.ts");
  const { withDedicatedNav } = await import("../app/nxm/_components/dedicated-nav.ts");
  for (const f of ["app/nxm/_pages/vps/content.ts", "app/nxm/_home/content.ts"]) {
    const src = read(f);
    const key = f.includes("_home") ? "HEADER_HTML = " : "BODY_HTML = ";
    const start = src.indexOf(key) + key.length;
    const html = JSON.parse(src.slice(start, src.indexOf(";\nexport const", start))) as string;
    assert.equal(withCyrusNav(html, false), html, `${f}: unchanged for everyone else`);
    const on = withCyrusNav(html, true);
    assert.equal((on.match(/href="\/nxm\/cyrus"/g) ?? []).length, 3, `${f}: desktop tab + products menu + mobile sheet`);
    // composes with the dedicated injection in either order
    assert.equal((withCyrusNav(withDedicatedNav(html, true), true).match(/href="\/nxm\/cyrus"/g) ?? []).length, 3);
  }
  assert.match(read("app/nxm/_components/NxmPage.tsx"), /withCyrusNav\(withDedicatedNav\(html, dedi\.allowed\), cy\.allowed\)/);
  assert.match(read("app/nxm/page.tsx"), /withCyrusNav\(header, cy\.allowed\)/);
  const links = [{ label: "Mod catalogue", href: "/mods" }, { label: "x", href: "/x" }];
  assert.deepEqual(cyrusFooterLinks("f-games", links, false), links);
  assert.deepEqual(cyrusFooterLinks("f-games", links, true).map((l) => l.href), ["/mods", CYRUS_FOOTER_LINK.href, "/x"]);
  assert.deepEqual(cyrusFooterLinks("f-products", links, true), links);
  assert.match(read("app/nxm/_components/NxmFooter.tsx"), /cyrusFooterLinks\(col\.id, col\.links, cy\.allowed\)/);
});

/** Every source file under a directory. */
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(path.join(ROOT, dir))) {
    const rel = `${dir}/${e}`;
    if (e === "node_modules" || e.startsWith(".")) continue;
    const st = statSync(path.join(ROOT, rel));
    if (st.isDirectory()) walk(rel, out);
    else if (/\.(tsx?|json|mjs)$/.test(e)) out.push(rel);
  }
  return out;
}

test("nothing outside the feature links to the unreleased /cyrus page", () => {
  const ALLOWED = (f: string) =>
    f === "lib/cyrus/public-gate.ts" ||
    f === "app/nxm/_components/cyrus-nav.ts" ||
    f.startsWith("app/nxm/cyrus/") ||
    f.startsWith("app/nxm/_pages/cyrus/") ||
    f === "app/nxm/_data/cyrus.ts" ||
    f === "app/nxm/_data/live-routes.json" ||
    f === "app/nxm/_seo/registry.ts" ||
    f.startsWith("components/cyrus/marketing/");
  // the page route itself (assets under /cyrus/... are fine)
  const LINK = /["'`](?:https?:\/\/[^"'`/]+)?(?:\/nxm)?\/cyrus(?=["'`?#])/;
  const hits: string[] = [];
  for (const f of [...walk("app"), ...walk("components"), ...walk("lib")]) {
    if (ALLOWED(f)) continue;
    if (LINK.test(read(f))) hits.push(f);
  }
  assert.deepEqual(hits, [], `unreleased /cyrus linked from: ${hits.join(", ")}`);
});

test("the page's game hosting links all exist on the live site", async () => {
  const live = new Set((JSON.parse(read("app/nxm/_data/live-routes.json")) as { exact: string[] }).exact);
  const src = read("app/nxm/_data/cyrus.ts");
  const routes = [...src.matchAll(/route: "(\/[a-z0-9-]+)"/g)].map((m) => m[1]);
  assert.equal(routes.length, 6);
  for (const r of routes) assert.ok(live.has(r), r);
});

test("plan estimates come from the real token tables (pure)", async () => {
  const { planCapacity } = await import("../app/nxm/_data/cyrus-plans.ts");
  const { DEFAULT_RESERVE_TABLE } = await import("../lib/cyrus/tokens/config.ts");
  const [katara] = planCapacity(750, ["katara"], DEFAULT_RESERVE_TABLE, 0.8);
  // 750 tokens / standard [60,140] -> 5..12 typical mods; edits on simple [30,70] * 0.8 -> 13..31
  assert.deepEqual(katara.mods, [5, 12]);
  assert.deepEqual(katara.small, [10, 25]);
  assert.deepEqual(katara.edits, [13, 31]);
  const all = planCapacity(10000, ["katara", "saka", "yakko"], DEFAULT_RESERVE_TABLE, 0.8);
  assert.deepEqual(all.map((c) => c.model), ["katara", "saka", "yakko"]);
  for (const c of all) { assert.ok(c.mods[0] <= c.mods[1]); assert.ok(c.edits[0] >= c.mods[0]); }
  // a bad factor never divides by zero or inflates
  assert.deepEqual(planCapacity(100, ["saka"], DEFAULT_RESERVE_TABLE, 0)[0].edits, planCapacity(100, ["saka"], DEFAULT_RESERVE_TABLE, 1)[0].edits);
});

test("demo routing: names first, aliases next, ask when no game is named (pure)", async () => {
  const { routePrompt, titleFrom } = await import("../components/cyrus/marketing/route.ts");
  const { GAMES, CATEGORIES } = await import("../lib/cyrus/data.ts");
  const games = GAMES.map((g) => ({ id: g.id, name: g.name, short: g.short, rgb: g.rgb, logo: g.logo ?? null, logoTone: g.logoTone ?? null, status: (g.real ? "live" : "soon") as "live" | "soon", categories: g.categories, aliases: g.aliases }));
  const cats = CATEGORIES.map(({ key, label, rgb, keywords }) => ({ key, label, rgb, keywords }));
  const r1 = routePrompt("Make me a mod for Minecraft where creepers drop diamonds", games, cats);
  assert.equal(r1.game?.id, "minecraft");
  const r2 = routePrompt("A frost-forged greatsword for Minecraft that freezes enemies", games, cats);
  assert.equal(r2.game?.id, "minecraft");
  assert.equal(r2.cat?.key, "weapons");
  assert.equal(routePrompt("smart raid alarms for Rust that ping my team", games, cats).game?.id, "rust");
  assert.equal(routePrompt("an oxide plugin for kits", games, cats).game?.id, "rust", "alias");
  assert.equal(routePrompt("a horde night for project zomboid", games, cats).game?.id, "zomboid");
  assert.equal(routePrompt("a better shop with coins", games, cats).game, null, "no game: ask, never guess");
  assert.equal(routePrompt("", games, cats).game, null);
  // two games named: the first one mentioned wins
  assert.equal(routePrompt("port my Valheim boss to Terraria", games, cats).game?.id, "valheim");
  assert.equal(titleFrom("A frost-forged greatsword for Minecraft: a custom netherite sword", games[0]), "Frost Forged Greatsword");
  assert.equal(titleFrom("make me a mod for Minecraft where creepers drop diamonds", games[0]), "Creepers Drop Diamonds");
  assert.equal(titleFrom("??", null), "Untitled mod");
});

