import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { db } from "../lib/db";

const EMAIL = "cyrus-preview@nxeon.test";
async function main() {
  const url = process.env.DATABASE_URL ?? "";
  if (!/127\.0\.0\.1:5433\/wt_/.test(url)) throw new Error("refusing: not the node-2 throwaway DB");
  await db.setting.upsert({ where: { key: "preview_access_emails_modbuilder" }, update: { value: EMAIL }, create: { key: "preview_access_emails_modbuilder", value: EMAIL } });
  // the public flag stays OFF (the gate is what we are checking)
  await db.setting.deleteMany({ where: { key: "cyrus_public_enabled" } });
  const user = (await db.user.findUnique({ where: { email: EMAIL } })) ?? (await db.user.create({ data: { email: EMAIL, passwordHash: "x", name: "Cyrus Preview", role: "CUSTOMER", emailVerifiedAt: new Date(), heardAboutUs: "other" } as never }));
  const other = (await db.user.findUnique({ where: { email: "someone@nxeon.test" } })) ?? (await db.user.create({ data: { email: "someone@nxeon.test", passwordHash: "x", name: "Not Preview", role: "CUSTOMER", emailVerifiedAt: new Date(), heardAboutUs: "other" } as never }));
  const plan = await db.plan.upsert({ where: { slug: "seed-mc-base" }, update: {}, create: { slug: "seed-mc-base", name: "seed base", cpuCores: 2, ramMB: 4096, diskGB: 40, priceCents: 999, active: false } });
  if (!(await db.gamePlan.findFirst({ where: { gameFamily: "minecraft" } }))) {
    await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "Minecraft — 4 GB", ramMB: 4096, cpuCores: 2, diskGB: 40, priceCents: 999, basePlanId: plan.id, active: true } });
    await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "Minecraft — 8 GB", ramMB: 8192, cpuCores: 4, diskGB: 80, priceCents: 1999, basePlanId: plan.id, active: true } });
  }
  const tok = async (id: string) => {
    const token = await new SignJWT({ sub: id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
    await db.userSession.create({ data: { userId: id, tokenHash: createHash("sha256").update(token).digest("hex") } });
    return token;
  };
  writeFileSync(".cymkt/session.json", JSON.stringify({ preview: await tok(user.id), other: await tok(other.id) }));
  console.log("seeded preview", user.id, "other", other.id);
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });
